-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(289, { "classic", "forever" }, { deDE = { progress = "Ich kann manchmal in meinen Träumen das unselige Stöhnen meiner Brüder hören! Bitte, guter Herr, befreit sie von ihren Fesseln und lasst ihre Schreie verstummen.", completion = "Ich danke Euch, {name}. Und den Dank meiner verfluchten Brüder habt Ihr ebenfalls." }, enUS = { progress = "In my dreams, I can sometimes hear the doomed moans of my brethren!  Please, good sir, free them from the bonds and quiet their cries.", completion = "My thanks to you, {name}.  And the gratitude of my cursed brethren goes to you as well." } })
apply(290, { "classic", "forever" }, { deDE = { progress = "Diese Truhe ist sicher verschlossen.", completion = "Der Schlüssel ist verrostet, passt aber einwandfrei ins Schloss." }, enUS = { progress = "This chest is securely locked.", completion = "The key is rusted but it fits the lock neatly." } })
apply(291, { "classic", "forever" }, { deDE = { progress = "Hmm... Es scheint, als würden meine Wachen neuerdings jeden Bittsteller durchlassen. Nun, was wollt Ihr? Fasst Euch kurz.", completion = "<Er überfliegt das Dokument.>\n\nVollmacht des KÖNIGS!? Hat Magni jetzt völlig den Verstand verloren? Und dieser schändliche Whitebeard... hat die Dinge selbst in die Hand genommen, was? Der Senat wird nicht erfreut sein, hiervon zu hören, nicht das kleinste bisschen.\n\nWas, Ihr seid immer noch hier? Geht, bevor ich die Wachen rufe!" }, enUS = { progress = "Hmm... it would seem that my guards are becoming less discriminatory with petitioners. Well, what do you want? Make it quick.", completion = "<He quickly peruses the report.>\n\nAuthority of the KING!? Has Magni taken complete leave of his senses! And that damnable Whitebeard... Taken matters into his own hands, has he? The Senate will not be pleased to hear about this, not one bit.\n\nWhat, are you still here? Go, before I call the guards!" } })
apply(292, { "classic", "forever" }, { deDE = { progress = "Dieser Säufer Fitzsimmons hat Euch zu mir geschickt? Nun, Ihr könnt ihm sagen, dass ich kein Ale übrig habe. Er wird wohl jemand anderes anbetteln müssen!", completion = "Ein Auge von Paleth? Erstaunlich! Hmm... irgendetwas stimmt nicht mit diesem hier. Ihr habt es auf einem der Schiffswracks gefunden? Das erklärt einiges! Allerdings... wusste ich gar nicht, dass sie in der dritten Flotte ein solches Auge hatten... \n\nKein Wunder, dass Fitzsimmons so verängstigt war. Ein verfluchtes Auge von Paleth ist kein Grund zur Fröhlichkeit." }, enUS = { progress = "That drunk Fitzsimmons sent you to me?  Well, you can tell him I don't have any extra ale.  He's going to have to panhandle someone else!", completion = "An Eye of Paleth?  Amazing!  Hmm...there's something wrong with this one.  You found it on one of those shipwrecks?  Well that explains it!  But...I didn't know they had such an Eye on the Third Fleet...\n\nIt's no wonder Fitzsimmons was so spooked.  A Cursed Eye of Paleth is no cause for mirth." } })
apply(293, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr da für eine Kugel? Sie sieht so... befleckt aus.", completion = "Ein Auge von Paleth. Aber dieses hat viel Leid gesehen... es muss Zeuge einer schrecklichen, grauenhaften Tragödie gewesen sein.\n\nLasst es mich reinigen, denn die Augen wurden geschaffen, um hell zu erstrahlen, und ihre Kräfte können sehr gefährlich sein, wenn sie wie dieses hier besudelt sind." }, enUS = { progress = "What is that orb you have?  It looks...soiled.", completion = "An Eye of Paleth.  But this one has seen much sorrow...it must have been witness to a terrible, terrible tragedy.\n\nLet me cleanse it, for the Eyes were created to shine bright, and their powers can be quite dangerous if tainted like this one." } })
apply(294, { "classic", "forever" }, { deDE = { progress = "Tötet 10 Scheckige Raptoren und 10 Scheckige Kreischer, {name}. Meine Mitarbeiter hatten das Schicksal nicht verdient, das ihnen zuteil wurde. Es ist an der Zeit, die Rechnung zu begleichen.", completion = "Töten ist ein schmutziges Geschäft, aber Ihr habt Eure Sache gut gemacht, {name}. Wenn ich nicht dazu verpflichtet wäre, hier beim Ausgrabungsleiter und Merrin zu bleiben, würde ich an Eurer Seite da unten Blut vergießen." }, enUS = { progress = "Kill 10 Mottled Raptors and 10 Mottled Screechers, {name}.  My co-workers did not deserve the fate that was brought upon them.  It's time to even the score.", completion = "Killing is a dirty business, but you did your job well, {name}.  If I weren't obligated to stay with the Prospector and Merrin, I'd be down there shedding blood right along side you." } })
apply(295, { "classic", "forever" }, { deDE = { completion = "Ihr habt beim Aufräumen unter diesen Raptoren phantastische Arbeit geleistet, {name}!" }, enUS = { completion = "You did a bang-up job of clearing out those Raptors, {name}!" } })
apply(296, { "classic", "forever" }, { deDE = { progress = "Ist Sarlatan tot? Seid Ihr dem Andenken der Gefallenen gerecht geworden?", completion = "Danke, {name}. Eure Anstrengungen hier werden nicht in Vergessenheit geraten. Viele unschuldige Zwerge starben an dieser Stätte, während sie einfach nur ihrer Arbeit nachgingen. Die Rache, die Ihr über diese bösen Kreaturen gebracht habt, sollte dafür sorgen, dass sie es sich zweimal überlegen, bevor sie je wieder König Magnis Untertanen angreifen." }, enUS = { progress = "Is Sarltooth dead? Have you redeemed the memory of the fallen?", completion = "Thank you, {name}.  Your efforts here will not be forgotten.  Many innocent Dwarves died at this site, simply doing their jobs.  The vengeance you delivered to those evil creatures should make them think twice before attacking King Magni's subjects ever again." } })
apply(297, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Götzen? Wir müssen sie studieren und Ironforge von unseren Ergebnissen berichten!", completion = "Ihr habt sie! Gut gemacht, {name}!\n\nUnd Ihr seht nicht einmal besonders angeschlagen aus, trotz all der wild gewordenen Troggs. Ich werde Euch im Auge behalten... Ihr seid viel versprechend." }, enUS = { progress = "Do you have those Idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, {name}!\n\nAnd you don't look too worse for wear, even with those berserk Troggs about.  I'm going to keep my eye on you...you show some promise." } })
apply(298, { "classic", "forever" }, { deDE = { progress = "Oh, ein Fortschrittsbericht von der Stätte? Sehr gut!", completion = "Pah! Ironband hat Probleme mit den Troggs. Ich frage mich, ob er das Sprengpulver will, um ihm bei seinen Ausgrabungen zu helfen oder um ihn bei seinen Bemühungen gegen die Trogg-Bestien zu unterstützen...\n\nNun ja, so oder so ist das gute Pulver sinnvoll eingesetzt!\n\nEs ist allerdings etwas seltsam, dass ich ihm vor ein paar Wochen eine Menge Sprengpulver geschickt habe. Ich frage mich ja, wo das hingekommen ist..." }, enUS = { progress = "Oh, a progress report from the site?  Very good!", completion = "Bah!  Ironband's having trouble with the Troggs.  I wonder if he wants that blastpowder to aid his digging, or to aid his efforts against the Trogg beasts...\n\nWell, either way it's powder well spent!\n\nBut what's strange is, I sent him plenty of blastpowder weeks ago.  I wonder where it went..." } })
apply(299, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die vier Fragmente bereits gefunden, {name}? Ados, Modr, Golm und Neru...", completion = "Ah, der Goazstein ist vollständig! Ausgezeichnete Arbeit, {name}. Wirklich ausgezeichnete Arbeit. Jetzt kann ich mit der kniffligen Übersetzung dieser Titanenschrift weitermachen. Ich kann bereits neue Worte erkennen! Hmm... es heißt hier \"Alte Götter... angekettet unter dem Land\". Dies ist der Anfang von etwas Epischem." }, enUS = { progress = "Have you uncovered the four fragments yet, {name}?   Ados, Modr, Golm and Neru...", completion = "Ah the Goaz Stone is complete!  Fine work, {name}.  Fine work indeed.  Now I can continue with the delicate translation of this Titan script.  I can make out new words already!  Hmm. . .it says here, \"Old Gods. . .Chained Beneath the Land.\"  This is the beginning of something epic." } })
apply(301, { "classic", "forever" }, { deDE = { progress = "Wir Stormpikes lassen uns nicht gern von unbedeutenden Angelegenheiten stören, {class}. Ich hoffe, Ihr bringt Neuigkeiten, die meine Aufmerksamkeit verdienen.", completion = "Verflucht sei Ironband! Ich habe ihm schon vor Wochen eine Ladung Sprengpulver geschickt, aber er erwähnt es nicht mal in diesem Bericht.\n\nAlso... wo ist das Sprengpulver hin?!?" }, enUS = { progress = "We Stormpikes don't like being bothered with trivial matters, {class}.  I hope you brought news worthy of my valuable attention.", completion = "Curse that Ironband!  I sent him a load of blastpowder weeks ago, but he's made no mention of it in this report.\n\nSo...where did the blastpowder go?!?" } })
apply(302, { "classic", "forever" }, { deDE = { completion = "Was? Stormpike will, dass Ihr die Lieferung persönlich zu Ironband bringt?\n\nIch... denke, das geht in Ordnung, aber das Problem ist, dass ich Huldar bereits mit den Trägern Miran und Saean losgeschickt habe. Ihr habt sie gerade verpasst, sie sind vor einer kurzen Weile erst aufgebrochen." }, enUS = { completion = "What? Stormpike wants you to personally see the shipment to Ironband?\n\nI... suppose that's fine, the only problem is, I've already sent Huldar with the porters, Miran and Saean. You just missed them, they left just a short while ago." } })
apply(303, { "classic", "forever" }, { deDE = { progress = "Roggo konnte keinen Kontakt zu den Reserven herstellen. Wir müssen offensiven Druck auf dieses Lager der Dunkeleisenzwerge ausüben, {class}. Und jetzt geht wieder da raus und erfüllt Eure Pflicht König Magni gegenüber!", completion = "Ihr habt Eure Befehle gut ausgeführt, {class}. Ihr habt bewiesen, dass Ihr ein tapferer Soldat und loyaler Diener König Magnis' seid, und dafür bewundere ich Euch. Durch den Druck, den Ihr auf das Lager der Dunkeleisenzwerge ausgeübt habt, haben wir jetzt eine Chance, sie für immer aus unseren Landen zu vertreiben... wenn nur die verdammte Reserve endlich auftauchen würde..." }, enUS = { progress = "Roggo has been unable to contact the reserve forces.  We need offensive pressure on that Dark Iron encampment, {class}.  Now get back out there and serve your duty to King Magni!", completion = "You upheld your orders well, {class}.  You have proven yourself to be a valiant soldier and loyal servant to King Magni and for that I salute you!  With the pressure you applied to the Dark Iron encampment, we now stand a chance of driving them off our lands for good. . .if only the damned reserve would show. . . ." } })
apply(304, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr Balgaras den Niederträchtigen schon aufspüren, {class}? Er weicht uns schon eine ganze Weile aus.", completion = "Balgaras der Niederträchtige ist endlich tot. Wenn sein Tod auch die vielen unschuldigen Zwerge nicht zurückbringt, die sinnlos durch seine Hand starben, so wird dies doch zum Seelenfrieden derer beitragen, die überlebt haben. Nachdem Balgaras nun tot ist, sollte es ein Leichtes sein, mit dem restlichen Dunkeleisenpack fertig zu werden. Jetzt müssen wir den Abschaum auslöschen, bevor ein neuer Anführer in diese Gegend entsandt wird.\n\nIhr habt Eure Sache gut gemacht, {class}." }, enUS = { progress = "Were you able to locate Balgaras the Foul yet, {class}?  He has been evading us for quite some time.", completion = "Balgaras the Foul is finally dead.  While his death will not bring back the many innocent dwarves who died needlessly by his hand, it will help to restore peace of mind to those who survived.  With Balgaras dead, the remaining Dark Iron scum should be easy enough to manage.  Now, we must wipe them out before a new leader is sent to these parts.\n\nYou have done well, {class}." } })
apply(305, { "classic", "forever" }, { deDE = { completion = "Oh, dank sei den Himmeln, dass Ihr hier seid!" }, enUS = { completion = "Oh, thank the heavens you are here!" } })
apply(306, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Merrin gefunden? Hat sie eine Nachricht geschickt?", completion = "Welch grausige Neuigkeiten! Immerhin haben 3 von ihnen überlebt. Doch wann wird das Töten endlich aufhören? Ich sehne mich nach dem Tag, an dem König Magnis Untertanen ohne Angst leben können." }, enUS = { progress = "Were you able to find Merrin?  Did she send word?", completion = "Such horrible news!  At least 3 of them survived.  But when will the killing end?  I long for the day when King Magni's subjects can live without fear." } })
apply(307, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Bergarbeiter-Ausstattung, {name}?", completion = "Habt Ihr da drin viele Kobolde gesehen? Ich kann den Befehl, sie aus der Mine zu werfen, kaum erwarten. Der Gedanke daran, wie ihre schmutzigen Hände in unserer Mine herumkratzen, verursacht mir Bauchschmerzen!" }, enUS = { progress = "Do you have that Miners' Gear, {name}?", completion = "Did you see a lot of Kobolds in there?  I can't wait for the order to clear them out of the mine.  The thought of their grimy hands clawing around our mine makes my stomach rumble!" } })
apply(309, { "classic", "forever" }, { deDE = { completion = "Oh, gelobt sei das Licht, dass das Pulver hier ist. Allerdings bringt Ihr auch Besorgnis erregende Neuigkeiten. Wenn ich nur daran denke, dass die Dunkeleisenzwerge Sympathisanten haben, die solches Material für ihre heimtückischen Pläne beschaffen können.\n\nDoch das ist eine Angelegenheit, um die sich jemand anderes zu gegebener Zeit kümmern muss. Ich muss dieses Pulver einer guten Verwendung zuführen." }, enUS = { completion = "Oh, thank the Light the powder is here. But it is troubling news that you bring as well. To think that the Dark Irons have sympathizers able to procure this sort of material for their dastardly plans.\n\nThat's a matter for someone else to consider, some other time. I must put this powder to good use." } })
apply(310, { "classic", "forever" }, { deDE = { progress = "Die Datumsangabe auf diesem Fass legt nahe, dass es demnächst angestochen werden wird.", completion = "Schnell stellt Ihr Marleths Fass voll Gerstenbräu zwischen die Fässer der Brauerei Donnerbräu." }, enUS = { progress = "The date on this barrel shows that it'll soon be tapped.", completion = "You quickly place Marleth's barrel of Barleybrew Scalder among the Thunderbrew barrels." } })
apply(311, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Austausch vollzogen?", completion = "Nicht schlecht, {name}! War es schwierig, an der Wache vorbeizukommen?\n\nEgal - vielen Dank, und wenn Ihr jemals ein Starkbier mit Pepp haben wollt, denkt an die Gerstenbräus!" }, enUS = { progress = "Did you make the switch?", completion = "Not bad, {name}!  Did you have a hard time getting past their guard?\n\nNo matter - many thanks, and if you're ever in need of stout with a kick, don't forget the Barleybrews!" } })
apply(312, { "classic", "forever" }, { deDE = { progress = "Habt Ihr es geschafft, an den Inhalt meines Fleisch-Spindes ranzukommen, {name}?", completion = "Was für eine gute Seele Ihr doch seid, {name}! Dank Eurer Tapferkeit werde ich nicht hungern müssen, wenn in der kalten Jahreszeit die Schneestürme toben." }, enUS = { progress = "Were you able to get into my meat locker, {name}?", completion = "What a kind soul you are, {name}!  Thanks to your bravery I won't find myself starving when the cold season flurries blow in." } })
apply(313, { "classic", "forever" }, { deDE = { progress = "He, {name}. Wart Ihr schon im altgedienten Bau? Diese Wendigos können ziemlich heftig sein.", completion = "Oh ja, diese Mähnen sind genau richtig! Ihr zeigt viel Schneid, {class} - ich wette, man kann noch viele großartige Taten von Euch erwarten." }, enUS = { progress = "Hey, {name}.  Been to the Grizzled Den yet?  Those Wendigos can be fierce.", completion = "Ah yes, these manes will work great!  You show a lot of grit, {class} - I wager we'll see great things from you." } })
apply(314, { "classic", "forever" }, { deDE = { progress = "Vagash terrorisiert immer noch die Herde! Bitte helft uns, indem Ihr die elende Bestie umbringt.", completion = "Sehr gut gemacht! Veron wird begeistert sein, wenn er die gute Nachricht vernimmt. Vagash zu töten, kann keine leichte Aufgabe gewesen sein. Ich schätze, Ihr werdet eines Tages Seite an Seite mit König Magnis Mannen an der Allianzfront kämpfen." }, enUS = { progress = "Vagash still terrorizes the herd!  Please help us by killing the wretched beast.", completion = "Very well done!  Veron will be so happy when he hears the good news.  To kill Vagash is no easy task.  I imagine one day you'll be fighting alongside King Magni's men on the Alliance Front." } })
apply(315, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Schimmerkraut? Ich habe eine Fuhre Starkbier so gut wie braufertig und möchte das Kraut versuchsweise in diese Mischung mit hineinwerfen.", completion = "Großartig! Ich kann es kaum erwarten, sie in einigen meiner Rezepte auszuprobieren. Ich glaube, in ein bestimmtes würde es wunderbar hineinpassen..." }, enUS = { progress = "Do you have that shimmerweed?  I almost have a batch of stout ready to brew, and I want to try throwing the weed in with this mixture.", completion = "Great!  I can't wait to use these in some of my recipes.  There's one in particular I think it'll work great in..." } })
apply(317, { "classic", "forever" }, { deDE = { progress = "Die Vorbereitungen laufen gut. Wie geht es mit der Jagd voran?", completion = "Bei Magnis Bart, Ihr habt wirklich ganz schön viel gejagt!! Danke, {name}." }, enUS = { progress = "Preparations are going well.  How goes your hunting?", completion = "By Magni's beard, you sure did a lot of hunting!!  Thank you, {name}." } })
apply(318, { "classic", "forever" }, { deDE = { completion = "Bellowfiz braucht etwas von meinem Immerschimmer? Hm... in Ordnung." }, enUS = { completion = "Bellowfiz needs some of my Evershine?  Hm...all right." } })
apply(319, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Euch um die wilden Tiere gekümmert?", completion = "Danke, {name}. Es wird angenehm sein, unser Handwerk auszuüben, ohne ständig irgendwelches Knurren und Schnauben vor dem Dorf zu hören." }, enUS = { progress = "Have you taken care of those wild animals?", completion = "Thank you, {name}.  It'll be nice to work our crafts without hearing so many growls and snorts outside the village." } })
apply(320, { "classic", "forever" }, { deDE = { progress = "Habt Ihr den Immerschimmer bekommen können?", completion = "Ja, das ist genau richtig. Ich denke, ich werde gleich mal eine Flasche aufmachen und einen Schluck zu mir nehmen..." }, enUS = { progress = "Did you get that Evershine?", completion = "Yes, this will do just fine.  I think I'll open a bottle right now and have a taste..." } })
apply(321, { "classic", "forever" }, { deDE = { completion = "Diese Truhe ist vollgesogen und seitlich aufgebrochen. Viele Klauenspuren verunstalten sowohl die Innen- wie auch die Außenseite der Truhe... als hätten Murlocs sie durchsucht und ihren Schatz gestohlen.\n\nDoch ganz tief in der Truhe versteckt findet sich ein einzelner Lichtschmiedeblock. Dummerweise werden noch viele weitere benötigt, wenn man genug Metall zusammenbekommen möchte, um eine Waffe daraus zu fertigen." }, enUS = { completion = "This chest is waterlogged, and its siding broken.  Many claw marks mar both the inside and outside of the chest...as if Murlocs have searched through it and stolen its treasure.\n\nBut tucked deep within the chest is a single Lightforge Ingot.  Unfortunately, many more will be needed if enough metal to fashion a weapon is to be gained." } })
apply(322, { "classic", "forever" }, { deDE = { progress = "Wie kann ich Euch behilflich sein, {class}?", completion = "Das ist eine ganz schöne Geschichte, die Ihr da erzählt. Und dann habt Ihr auch noch Lichtgeschmiedetes Eisen! Ich habe seit Jahren nicht mehr mit dieser Art Eisen gearbeitet. Es wird mir eine Ehre sein, es erneut zu formen. Und Ihr müsst später mit der Geschichte Eurer Schlacht gegen den Totenbeschwörer zurückkehren.\n\nAber wir greifen den Dingen vor. Erstmal kümmen wir uns um Eure Waffe gegen Morbent Fel..." }, enUS = { progress = "How might I ply my craft for you, {class}?", completion = "That is quite a tale you have.  And lightforge iron!  Not for years have I worked with such a metal.  It will be an honor to craft with it again.  And you must return to me later with the story of your battle against the Necromancer.\n\nBut we get ahead of ourselves.  First, your weapon against Morbent Fel..." } })
apply(323, { "classic", "forever" }, { deDE = { progress = "Kämpft hart, {name}. Und verzweifelt nicht, denn die Verzweiflung ist die größte Waffe des Bösen.", completion = "Euer Kampfgeschick, {name}, steht außer Frage. Eure Entschlossenheit könnte uns tatsächlich das Ende von Morbent Fel erleben lassen!" }, enUS = { progress = "Battle hard, {name}.  And do not despair, for despair is evil's greatest weapon.", completion = "Your skill in combat, {name}, can not be doubted.  Your resolve may yet see us through to the end of Morbent Fel!" } })
apply(324, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Lichtgeschmiedetes Eisen gefunden, das Ihr braucht?", completion = "Ah, Ihr habt es bekommen! Jetzt lasst uns dieses Lichtgeschmiedetes Eisen in eine nützliche Form hämmern, hm?" }, enUS = { progress = "Did you find the lightforge iron you need?", completion = "Ah, you found them!  Now let's get this lightforge iron hammered into something useful, eh?" } })
apply(325, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Ihr wart nicht allzu lange weg, aber ich sehe ein Feuer in Euren Augen, das dort vorher noch nicht leuchtete.", completion = "Ah, das wird Sicherheit gegen die Satanskreatur Morbent Fel geben! Gut gemacht!\n\nIhr seid bereit. Morbent Fel wird fallen." }, enUS = { progress = "Hello, {name}.  You haven't been gone that long, but I see a fire in your eyes I did not see before.", completion = "Ah, this will be proof against the fiend Morbent Fel!  Well done!\n\nYou are ready.  Morbent Fel will fall." } })
apply(328, { "classic", "forever" }, { deDE = { progress = "Die Geldkassette ist erstaunlich groß, mit Bronze beschlagen, sehr stabil gebaut und sehr schwer.", completion = "Als Ihr die Geldkassette öffnet, wird klar, dass dies der Ort ist, an dem Herod seine wertvolleren Münzen und Gegenstände aufbewahrt." }, enUS = { progress = "The strongbox is bound in bronze, very sturdy, and very heavy.", completion = "Opening the strongbox, it's clear that this is where Herod keeps his more valuable coins and items." } })
apply(329, { "classic", "forever" }, { deDE = { progress = "Habt Ihr herausgefunden, wer von Thorsens Geheimnis wusste? Gibt es einen Verräter unter uns?", completion = "Danke, {name}. Diese Notiz ist der Hinweis, den wir brauchen, um den Verräter aufzustöbern!" }, enUS = { progress = "Did you discover who knew Thorsen's secret?  Is there a traitor among us?", completion = "Thank you, {name}.  This note is the clue we need to root out the traitor!" } })
apply(330, { "classic", "forever" }, { deDE = { completion = "Oh, klar kann ich das für Euch überprüfen. Mal sehen... letzte Woche war es... \n\n... nun, es war Gefreiter Merle, der mit Thorsen eingeteilt war. Sie hatten die gesamte letzte Woche die gleichen Patrouillenzeiten." }, enUS = { completion = "Oh, yes I can check that for you.  Let's see...last week it was...\n\n...why, it was Private Merle scheduled with Thorsen.  They had the same patrol times all of last week." } })
apply(331, { "classic", "forever" }, { deDE = { completion = "Es schmerzt mich, herauszufinden, dass es Merle war, der uns verraten hat. Er war immer ein tapferer Soldat, und ich dachte, sein Herz sei rein. Aber es ist eine große Erleichterung, dass Ihr ihn entlarvt habt - mit einem Spion wie ihm unter uns... würden wir Colonel Kurzen nicht lange standhalten." }, enUS = { completion = "It pains me to find out it was Merle who betrayed us.  He has always been a brave soldier, and I had thought his heart was true.  But it is a great relief to have found him out - with a spy like him among us...we would not last long against Colonel Kurzen." } })
apply(332, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt und fühlt Euch willkommen, edler Herr. Habt Ihr schon einmal einen unserer ausgezeichneten Weine versucht?", completion = "Ah, Ihr wart also bei Renato? Na dann, hier, bitte, werter Herr. Eine Flasche unseres außergewöhnlichen Pinot Noir. Ihr werdet nirgendwo in Azeroth etwas Vergleichbares finden." }, enUS = { progress = "Greetings and welcome, master.  Have you yet tried one of our fine wines?", completion = "Ah, so you've seen Renato?  Well here you are, sir.  A bottle of our special pinot noir.  You'll not find its equal in all of Azeroth!" } })
apply(334, { "classic", "forever" }, { deDE = { progress = "Seid Ihr hier, um Kleidung zu kaufen?", completion = "Oh, verflucht! Ich dachte, wenn ich mein Nähzeug vergesse, muss ich heute nicht arbeiten. Ich schätze, jetzt muss ich den Larsons beim Nähen helfen... \n\nNa ja. Ich denke, das Vergnügen muss wohl noch etwas warten." }, enUS = { progress = "Are you here to buy clothes?", completion = "Oh, blast!  I thought forgetting my kit would free me from work.  Now I guess I'll have to help the Larsons with their sewing...\n\nOh, well.  Fun will come later I guess." } })
apply(335, { "classic", "forever" }, { deDE = { progress = "Wishock wird bald genug Unterstützung haben, um uns jede Menge Ärger zu machen. Habt Ihr es endlich geschafft, Euch die Tilloaträne oder die Bisamwurzel anzueignen?", completion = "Ganz exzellent! Dies sind wirklich sehr schöne Exemplare!" }, enUS = { progress = "Wishock will soon garner enough support to cause us much grief.  Were you able to obtain the Tear of Tilloa or Musquash Root yet?", completion = "Most excellent! These are fine samples indeed!" } })
apply(336, { "classic", "forever" }, { deDE = { progress = "Seht Ihr nicht, dass ich beschäftigt bin? Meine Worte müssen gehört werden! Ich bin sehr wichtig für die Zukunft dieses Königreichs!\n\nOh... was habt Ihr denn da? Na, das sieht doch nach einem erfrischenden Getränk aus...", completion = "Ah, danke, dass Ihr mir dieses lecker aussehende Starkbier gebracht habt, Diener. Hier habt Ihr eine Kupfermünze. Und jetzt verschwindet aus meinem Blickfeld und lasst mich mein Getränk genießen." }, enUS = { progress = "Can you not see that I am busy?  My words must be heard!  I am very important to the future of this Kingdom!\n\nOh... what have you there?  Why it looks like a refreshing drink...", completion = "Ah, thank you for bringing me this fine looking stout, servant.  Here's a copper for you.  Now, out of sight with you and let me enjoy my drink!" } })
apply(337, { "classic", "forever" }, { deDE = { progress = "Oh! Was ist denn das für ein altes Buch, was Ihr da habt? Kann ich es mal sehen?", completion = "Ach du liebe Güte! Dieses Buch hat zuletzt in diesen Regalen gelegen, noch bevor Stormwind vor vielen Jahren wieder aufgebaut wurde. Es muss natürlich restauriert werden, denn es ist in einem üblen Zustand, aber es wäre mir eine Ehre, es in unsere Sammlung seltener Bücher aufzunehmen.\n\nDanke, werter Herr. Bitte nehmt dies als Bezahlung dafür an, dass Ihr das Buch zurückgebracht habt." }, enUS = { progress = "Ooh!  What's that old book you have there?  Can I see it??", completion = "Oh my!  This book hasn't rested on these shelves since before the rebuilding of Stormwind, years ago.  It will have to be restored of course, it's in bad shape, but I would be honored to place it within our rare books collection.\n\nThank you, sir.  Please accept this as payment for returning the book!" } })
apply(338, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Kapitel bereits zusammengefügt, {name}?", completion = "Ihr habt mir sicherlich einen Haufen Ärger erspart, {name}! Ich kann Euch gar nicht genug danken. Es dürfte nun nicht mehr lange dauern, bis man Meister Nesingwarys Buch in Bibliotheken überall auf der Welt finden wird." }, enUS = { progress = "Have you assembled the chapters yet, {name}?", completion = "You've certainly saved me a heap of trouble, {name}!  I can't thank you enough.  It shouldn't be long now until we see Master Nesingwary's book in libraries throughout the world!" } })
apply(339, { "classic", "forever" }, { deDE = { progress = "Ich nehme nicht an, dass Ihr es geschafft habt, die Seiten 1, 4, 6 und 8 aufzuspüren? Uns fehlen nur diese vier, um Kapitel I wieder zusammenzusetzen.", completion = "Endlich! Kapitel I ist vollständig!" }, enUS = { progress = "I don't suppose you were able to track down pages 1, 4, 6 and 8?  Those four are all we need to piece Chapter I back together.", completion = "At last!  Chapter I is complete!" } })
apply(340, { "classic", "forever" }, { deDE = { progress = "Wir brauchen immer noch die Seiten 10, 11, 14 und 16, um Kapitel II zu vollenden, {name}.", completion = "Kapitel II ist endlich vollständig! Gut gemacht!" }, enUS = { progress = "We still need pages 10, 11, 14 and 16 to complete Chapter II, {name}.", completion = "Chapter II is finally complete!  Well done!" } })
apply(341, { "classic", "forever" }, { deDE = { progress = "Hattet Ihr Glück mit den Seiten 18, 20, 21 oder 24? Das sind die einzigen, die wir brauchen, um Kapitel III zusammenzusetzen.", completion = "Puh! Gute Arbeit, {name}. Kapitel III ist jetzt wieder beisammen!" }, enUS = { progress = "Any luck with pages 18, 20, 21 or 24?  Those are the only ones we need to piece together Chapter III.", completion = "Phew!  Good work, {name}.  Chapter III is now back together in one piece!" } })
apply(342, { "classic", "forever" }, { deDE = { progress = "{name}, wir brauchen nur drei Seiten, um Kapitel IV fertig zu stellen. Habt Ihr mittlerweile die Seiten 25, 26 oder 27?", completion = "Phantastisch! Jetzt haben wir Kapitel IV fertig!" }, enUS = { progress = "We just need three pages to finish off Chapter IV, {name}.  Do you have pages 25, 26 or 27 yet?", completion = "Superb!  We now have Chapter IV ready to go!" } })
apply(343, { "classic", "forever" }, { deDE = { completion = "Metallurgie? Oh ja, wir haben viele Bücher über dieses Thema, und wir helfen Bruder Kristoff gern mit seiner Rede! Nun sagt... welches Buch genau war das noch gleich, das der gute Bruder benötigt?" }, enUS = { completion = "Metallurgy?  Ah yes, we have many books on the subject, and are happy to aid Brother Kristoff with his speech!  Now...which particular book was it the good brother needed?" } })
apply(344, { "classic", "forever" }, { deDE = { completion = "Herr Sheaf möchte wissen, wo sein Buch ist? Nun, das ist etwas peinlich. Ich habe das Buch, aber ich bin immer noch dabei, es abzuschreiben und daher noch nicht wirklich bereit, das Original wieder herzugeben." }, enUS = { completion = "Mr. Sheaf is wondering where his book is?  Well this is a tad embarrassing.  I have the book, but I'm still making my copy and I'm not quite ready to give the original up!" } })
apply(345, { "classic", "forever" }, { deDE = { completion = "Ihr braucht was?? Vielleicht ist es Euch nicht aufgefallen, aber wir sind damit beschäftigt, Seenhains Verteidigungsanlagen zu befestigen und die Schäden von den letzten Orcangriffen zu reparieren. Wenn Ihr Rethbaneisenerz braucht, dann müsst Ihr es Euch schon selbst holen!" }, enUS = { completion = "You need what??  Maybe you haven't noticed, but we're busy fortifying Lakeshire's defenses and repairing damage from recent orc attacks.  If you need Rethban Iron Ore, you'll have to get it yourself!" } })
apply(346, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr das Buch finden?", completion = "Das ist es! Danke, {name}. Möge das Licht Euren Körper und Eure Seele hell erleuchten!" }, enUS = { progress = "Were you able to find the book?", completion = "That's the one!  Thank you, {name}.  May the Light shine brightly upon both your body and spirit!" } })
apply(347, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Rethbanerz?", completion = "Oh, prächtig! Ich kann dieses Erz verwenden, um meine Farbtinte herzustellen, und kann dann die Abschrift von \"Belastbarkeit von Eisen\" fertig stellen.\n\nDanke, {name}!" }, enUS = { progress = "Do you have the Rethban Ore?", completion = "Oh, splendid!  I can use this ore to make my dye, and then can finish copying The Stresses of Iron.\n\nThank you, {name}!" } })
apply(348, { "classic", "forever" }, { deDE = { progress = "... Mutter?\n\n... so kalt... \n\n... ich fahre hinab in den wirbelnden Nether... h-h-h-halt mich fest, Mutter...", completion = "... fühle die Kraft zurückkehren... \n\nWo bin ich? Booty Bay? Ach du meine Güte! Ich hatte einen seltsamen Traum... \n\n... die Schwäche hat mich nicht vollständig verlassen..." }, enUS = { progress = "....mother?\n\n...so cold...\n\n...heading into the Twisting Nether...h-h-h-hold me mother....", completion = "...feel strength returning....\n\nWhere might be?  Booty Bay?  Oh my!  I had the strangest dream...\n\n...the weakness has not completely left me...." } })
apply(350, { "classic", "forever" }, { deDE = { completion = "Macht Ihr Witze? Shaw bittet mich erneut um Hilfe? Der hat Nerven...\n\nDie Bruderschaft der Defias, sagt Ihr? Tja, Ihr seid wirklich der Überbringer wunderbarer Neuigkeiten, was? Als Nächstes werdet Ihr mir erzählen, dass Deathwing noch am Leben sei und die Stadt angreift.\n\nNa gut, erzählt mir alles von Anfang an. Und lasst nichts aus, was Euch vielleicht nicht wichtig erscheint. Ich muss alles wissen." }, enUS = { completion = "You're kidding? Shaw wants my help again? Of all the nerve...\n\nThe Defias Brotherhood, you say? Well, you're certainly the bearer of wonderful news, aren't you? Next you're going to tell me that Deathwing is still alive and attacking the city.\n\nAll right, tell me everything from the beginning. And don't leave out something you think might not be important. I need to know it all." } })
apply(351, { "classic", "forever" }, { deDE = { progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-17/TN funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"" }, enUS = { progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover.  The beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-17/TN is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"" } })
apply(353, { "classic", "forever" }, { deDE = { progress = "Ihr seid den ganzen weiten Weg von Stormwind gekommen? Ich habe gehört, es wird da unten in den Menschenlanden dank herumlaufender Briganten und Orcs etwas brenzlig. An einem solchen Ort kann ein {class} sich perfekt beweisen!", completion = "Aha! Grimand hat also endlich meine Axt fertig gestellt! Ich kann es kaum erwarten, sie an einigen Troggs und Kobolden auszuprobieren!\n\nVielen Dank, {name}. Ihr habt für diese Lieferung eine weite Strecke zurückgelegt. Hier habt Ihr ein paar Münzen für eure Bemühungen." }, enUS = { progress = "You come all the way from Stormwind?  I hear it's getting dicey down there in the {race} lands, with brigands and orcs running about.  A perfect place for a {class} to prove their worth!", completion = "Aha!  So Grimand finally finished my axe!  I can't wait to try it against some troggs and kobolds!\n\nMany thanks, {name}.  It was a long distance to travel for this delivery.   Here are some coins for your efforts." } })
apply(354, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die sterblichen Überreste der Agamands? Sind diese verfluchten Bestien endlich vernichtet?", completion = "Rache hat einen süßen Geschmack, findet Ihr nicht? Als Ihr die Agamands vernichtet habt, habt Ihr da irgendeinen Hinweis auf einen freien Willen in ihnen bemerkt? Ich hoffe es. Ich hoffe, sie hatten Angst, bevor sie in die Vergessenheit zerschlagen wurden.\n\nDas ist eine närrische Hoffnung, ich weiß. Aber es ist dennoch eine Hoffnung, die ich hege." }, enUS = { progress = "Do you have the remains of the Agamands?  Are those cursed beasts finally destroyed?", completion = "Revenge has a sweet taste, don't you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.\n\nIt is a foolish hope, I know.  But it is a hope I foster nonetheless." } })
apply(355, { "classic", "forever" }, { deDE = { completion = "Coleman erzählt Gutes über Euch, {name}, wenn er von Euren erfolgreichen Vorstößen in Agamands Mühlen spricht.\n\nDie Verlassenen brauchen Eure Talente erneut..." }, enUS = { completion = "Coleman speaks well of you, {name}, telling of your successful forays into the Agamand Mills.\n\nThe Forsaken have need of your talents once again..." } })
apply(356, { "classic", "forever" }, { deDE = { progress = "Habt Ihr einen Bericht von Eurer Patrouille?", completion = "Sehr gut. Eure Anstrengungen helfen sehr dabei, die Geißel in Schach zu halten. Meinem Vorgesetzten, Exekutor Zygand, wird eine Empfehlung zugehen." }, enUS = { progress = "Do you have a report of your patrol?", completion = "Very good.  Your efforts do much to keep the Scourge at bay.  A commendation will be sent to my superior, Executor Zygand." } })
apply(357, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr das Buch beschafft?", completion = "Sehr gut, {name}. Ich werde dieses Buch studieren und die Identität des Lichs herausfinden. Ihr habt Eurer Königin gut gedient.\n\n\n\nErstaunlich! Das Buch, das Ihr besorgt habt, gehört keinem Geringeren als Gunther Arcanus!\n\nGunther war ein bewanderter Totenbeschwörer im Leben; er und ich waren Freunde und Waffengefährten, vor der Seuche. Und nach diesem Buch zu urteilen, wurde er im Tode noch mächtiger.\n\nSeine Fähigkeiten wären ein großer Segen für uns." }, enUS = { progress = "{name}, have you acquired the book?", completion = "Very good, {name}.  I will study this book and determine the identity of that lich.  You have served your Queen well.\n\n\n\nAstonishing!  The book you retrieved belongs to no one other than Gunther Arcanus!\n\nGunther was a skilled Necromancer in life; he and I were friends and comrades-in-arms, before the Plague.  And judging from his book he has grown even more powerful in death.\n\nHis skills would be a great boon to us." } })
apply(358, { "classic", "forever" }, { deDE = { progress = "Ist Eure Aufgabe abgeschlossen? Habt Ihr diese Hundeviecher vernichtet und sie ihres Sekrets beraubt?", completion = "Meisterlich erledigt, {name}. Die Geißel irrt sich, wenn sie denkt, dass sie diese Leichen gegen uns verwenden könnte, und die Flüssigkeit, die Ihr von den  der Moderfellsklaven gesammelt habt, wird von unseren Apothekern untersucht werden. Vielleicht enthält sie Geheimnisse, die wir gegen sie verwenden können.\n\nWie gesagt, gut gemacht. Aber unser Kampf geht weiter, und dieser Konflikt wird Euch sicher noch mehr Möglichkeiten bieten, den Verlassenen Euren Wert zu beweisen." }, enUS = { progress = "Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?", completion = "Expertly done, {name}.  The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by our Apothecaries.  It may have secrets we can use against them.\n\nAs I said, well done.  But our struggle continues, and the conflict will surely offer you more chances to prove your worth to the Forsaken." } })
apply(359, { "classic", "forever" }, { deDE = { completion = "Magistrat Sevren will einen Bericht? Nun gut: Die Verteidiger auf dem Bollwerk halten den Großteil der Geißel in Schach, aber gelegentlich schlüpfen ein paar durch. \n\nWir haben sporadisch Aktivitäten der Geißel östlich dieses Postens gesichtet, und diese häufen sich um Balnirs Bauernhof." }, enUS = { completion = "Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.\n\nWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead." } })
apply(360, { "classic", "forever" }, { deDE = { completion = "Es ist beunruhigend zu hören, dass die Geißel am Bollwerk vorbeischlüpft. Der Lichkönig und seine Diener greifen uns unaufhörlich an.\n\nAber wir werden nicht nachgeben. Er wird nicht noch einmal von uns Besitz ergreifen!" }, enUS = { completion = "It is troubling to hear of the Scourge slipping past the Bulwark.  The Lich King and his minions are ceaseless in their assaults.\n\nBut we will not give in.  He will not take us again!" } })
apply(361, { "classic", "forever" }, { deDE = { progress = "Ja?", completion = "Oh... mein armer Thurman! Ich habe ihn angefleht, Agamands Mühlen mit mir und meinem Vater zu verlassen, aber seine Familienbande waren zu stark! Und ich habe es genau gewusst! Ich wusste einfach, dass Brand ihm Böses wollte! Oh, verflucht seien diese Seuche und die Geißel!\n\n<Yvettes Gesicht glättet sich und wird dann kalt.>\n\nAber Selbstvorwürfe sind etwas für die Schwachen. Als eine Verlassene habe ich neue Ziele, und Liebe ist keines davon. Ich danke Euch, dass Ihr diesen Brief überbracht habt, denn ich hatte mich schon gefragt, was mit meiner alten Liebe geschehen war.\n\nDoch dieses Leben ist vorüber. Auf ewig." }, enUS = { progress = "Yes?", completion = "Oh...my poor Thurman!  I begged him to leave Agamand Mills with me and my father, but his family loyalty was too strong!  And I knew it!  I just knew it that Brand meant him harm!!  Oh, curse this Plague, and the Scourge!\n\n<Yvette's face then smoothes and grows cold.>\n\nBut regrets are for the weak.  As a Forsaken, I have new goals and love is not one of them.  I would thank you for delivering this letter, for I had wondered what happened to my past love.\n\nBut that life is over.  Forever." } })
apply(362, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Devlin gefunden?", completion = "Danke. Devlins Knochen werden eine gute Trophäe abgeben.\n\nWenn mein kaltes Herz überhaupt Wärme finden kann, dann in dem Wissen, dass die Agamands vernichtet sind. Sie haben mich und meine Familie im Stich gelassen, als die Seuche kam - jetzt schwöre ich, dass ich ihre Überreste unter meiner Sohle zermalmen werde!" }, enUS = { progress = "Did you find Devlin?", completion = "Thank you.  Devlin's bones will rest nicely on my mantle.\n\nIf my cold heart can find warmth, it is in knowing that the Agamands are destroyed.  They failed me and my family when the Plague came - now I swear I will smash their remains under my heel!" } })
apply(363, { "classic", "forever" }, { deDE = { completion = "Noch einer der wandelnden Toten, hm? Muss ein ziemlicher Schock gewesen sein, so in der Gruft aufzuwachen, wo es nur Kälte und Mordo gab, um Euch zu begrüßen... \n\nIch sehe Verwirrung in Eurem Gesicht. Lasst mich mal versuchen, Euch unsere... Situation... zu erklären.\n\nWir wurden durch unsere neue Anführerin, Lady Sylvanas, von der Kontrolle durch den Lichkönig befreit. Die dunkle Fürstin führt uns in unserem Krieg gegen die verhasste Geißel und die Bastionen der Menschheit, die jeden unserer Schritte verfolgen." }, enUS = { completion = "Another of the walking dead, hm? Must have been quite a shock, waking up in the crypt with only the cold and Mordo to greet you...\n\nI see the confusion on your face. Let me try to explain our... situation... to you.\n\nWe have been freed from the control of the Lich King by our new leader, Lady Sylvanas. The Dark Lady guides us in our war against the hated Scourge and the holdouts of humanity who dog our every step." } })
apply(364, { "classic", "forever" }, { deDE = { completion = "Es ist schade, dass die Geißel nicht bei uns eingegliedert werden kann, denn ihre große Zahl wäre in den kommenden Schlachten sehr nützlich.\n\nDoch sie werden sich uns nicht anschließen, und daher haben wir keine andere Wahl, als sie zu vernichten." }, enUS = { completion = "It is unfortunate that the Scourge cannot be brought into the fold, their large numbers would be useful in the battles ahead.\n\nBut they will not join us, so we have no choice but to destroy them." } })
apply(365, { "classic", "forever" }, { deDE = { progress = "Todeswache Simmer ließ mich wissen, dass Ihr mich mit einigen dringend benötigten Reagenzien versorgen würdet. Habt Ihr bereits 10 Kürbisse gesammelt, {name}?", completion = "Ihr habt Eure Befehle gut ausgeführt, {class}. Ihr habt Euch als eine echte Hilfe für die Armee der dunklen Fürstin erwiesen." }, enUS = { progress = "Deathguard Simmer sent word that you were going to provide me with some much needed reagents.  Were you able to gather 10 pumpkins yet, {name}?", completion = "You have performed your bidding well, young {class}.  You are proving yourself to be quite an asset to The Dark Lady's army." } })
apply(366, { "classic", "forever" }, { deDE = { progress = "Eure Meister sind Narren, Euch hierher zu entsenden, denn ich werde niemals wieder ein Sklave der Geißel sein!", completion = "Mein Buch?!? Also wart Ihr der Dieb, der es stahl!\n\nDoch... was ist das für eine neue Verzauberung darauf... Bethor? Er ist in Lordaeron?\n\nWenn es ihn immer noch gibt, dann konnte er sich vielleicht ebenfalls dem Zugriff des Lichkönigs entziehen..." }, enUS = { progress = "Your masters are fools to send you here, for I will never again be a Scourge slave!", completion = "My book?!?  So you were the thief who stole it!\n\nBut...what is this new enchantment upon it...Bethor?  He is in  Lordaeron?\n\nIf he still exists, then perhaps he too escaped from the Lich King's grasp..." } })
apply(367, { "classic", "forever" }, { deDE = { progress = "Habt Ihr 5 Phiolen Schattenhundblut gesammelt, {name}? Die Zeit drängt!", completion = "Das habt Ihr gut gemacht, {name}, und ich danke Euch für Eure Mühen." }, enUS = { progress = "Have you collected 5 vials of darkhound blood yet, {name}? Time is fleeting!", completion = "You have done well, {name} and I thank you for your efforts." } })
apply(368, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr 5 Finsterflossenschuppen von den Murlocs beschaffen können?", completion = "Die Schuppen sind perfekt, {name}. Genau das, was ich für dieses Gebräu brauche." }, enUS = { progress = "{name}, were you able to obtain 5 Vile Fin Scales from the Murlocs?", completion = "The scales are perfect, {name}. Exactly what I needed for this concoction." } })
apply(369, { "classic", "forever" }, { deDE = { progress = "Habt Ihr endlich etwas Gift eines heimtückischen Nachtwebers, {name}? Das ist die letzte Komponente, die mir fehlt, um mein Experiment zu testen.", completion = "Ah, dieses Gift wird genau richtig sein, {name}. Alles andere wurde bereits mit meinem Gebräu verkocht. Jetzt bin ich endlich so weit, diesen neuen tödlichen Erreger auszuprobieren!" }, enUS = { progress = "Do you have some venom from a Vicious Night Web Spider yet, {name}?  It's the final component I need in order to test my experiment.", completion = "Ah, this venom will do perfectly, {name}.  Everything else has been added to my concoction and boiled down.  Finally, I am ready to try this new deadly agent!" } })
apply(370, { "classic", "forever" }, { deDE = { completion = "Perrines Tod wird die dunkle Fürstin zweifelsohne zufrieden stellen. Ihr habt Eure Befehle gut ausgeführt, {class}." }, enUS = { completion = "Captain Perrine's death will undoubtedly please The Dark Lady.  You have performed your duty well, {class}." } })
apply(371, { "classic", "forever" }, { deDE = { completion = "Captain Vachons Tod wird den Vormarsch des Scharlachroten Kreuzzugs in Tirisfal deutlich verlangsamen. Aber es lauern noch andere Gefahren." }, enUS = { completion = "Captain Vachon's death will slow down the Scarlet Crusade's advancement in Tirisfal quite a bit.  But other threats loom." } })
apply(372, { "classic", "forever" }, { deDE = { completion = "Das habt Ihr sehr gut gemacht, {class}. Dank unnachgiebiger Krieger wie Euch, die im Namen der Verlassenen Siege davontragen, ist unser Volk einen Schritt näher dran, Arthas ein für alle Mal zu besiegen. Ich habe ein gutes Gefühl bei Euch, Kamerad." }, enUS = { completion = "You have done extremely well, {class}.  With ruthless fighters like you conquering in the name of The Forsaken our race is one step closer to defeating Arthas once and for all.  I have a good feeling about you, comrade." } })
apply(373, { "classic", "forever" }, { deDE = { progress = "Ja? Kann ich Euch irgendwie helfen?", completion = "Edwin van Cleef, sagt Ihr? Mit einem Brief von meiner toten Großmutter hätte ich eher gerechnet... Ihr habt ihn also getötet? Verzeiht, wenn ich das sage, aber ich bin etwas überrascht. Er war ein unvergleichlicher Krieger in seinen jungen Jahren. Lasst mich mal sehen, weswegen er mir nach so vielen Jahren auf einmal schreiben muss.\n\n<Baros überfliegt den Brief.>\n\nEdwin... Die Jahre haben dich offensichtlich kein bisschen verändert, immer noch der alte Idealist und Romantiker. Es kümmert ihn nicht, wen er verletzt, {name}. Die Rache hat ihn verzehrt. Allerdings weiß ich nicht, ob ich ihm daraus einen Vorwurf machen kann." }, enUS = { progress = "Yes? Is there something I can help you with?", completion = "Edwin VanCleef, you say? I would as much expect a letter from my dead grandmother... So you've killed him then? Pardon me in saying, but I'm somewhat surprised. He was a peerless fighter in his younger years. Let's see what he finds the need to write to me about after so many years.\n\n<Baros peruses the letter.>\n\nEdwin... I see the years haven't changed you a bit, an idealist as ever, and a romantic. He doesn't care who he hurts, {name}. Revenge has consumed him. But then, I'm not sure I can blame him." } })
apply(374, { "classic", "forever" }, { deDE = { progress = "Habt Ihr bereits 10 scharlachrote Insignienringe gesammelt, {class}?", completion = "Varimathras wäre stolz. Ihr dient Euren Anführern gut, {class}." }, enUS = { progress = "Have you collected 10 Scarlet Insignia Rings yet, {class}?", completion = "Varimathras would be proud.  You serve your leaders well, {class}." } })
apply(375, { "classic", "forever" }, { deDE = { progress = "Habt Ihr schon fünf Nachtsaugerpelze und etwas groben Faden, {name}?", completion = "Ich weiß Eure Mühen zu schätzen, {name}. Möge Sylvanas Eure Tapferkeit eines Tages anerkennen..." }, enUS = { progress = "Do you have five Duskbat Pelts and some Coarse Thread yet, {name}?", completion = "I appreciate your efforts, {name}.  May Sylvanas recognize your bravery one day. . . ." } })
apply(376, { "classic", "forever" }, { deDE = { progress = "Bemüht Euch, unverletzt zu bleiben, bis ich Euch irgendeine Rüstung besorgt habe.", completion = "Danke, {name}. Diese Rüstung sollte Euch etwas helfen.\n\nHoffentlich hilft sie Euch mehr als ihrem letzten Träger..." }, enUS = { progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, {name}. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it..." } })
apply(377, { "classic", "forever" }, { deDE = { progress = "So lange einem Leichenschänder wie Dextren Ward erlaubt wird, weiterzuleben, ist das Verrat an der Gerechtigkeit. Kehrt zu mir zurück, sobald Lord Ebonlockes Todesurteil an diesem Entweiher Ward vollstreckt wurde. Wir werden für die Familien der Toten den Schlussstrich ziehen, den sie verdienen und, noch wichtiger, dem Oberhaus in Stormwind eine klare Botschaft senden.", completion = "Dextren Ward hat also endlich für seine Verbrechen an der Menschheit bezahlt? Ich wünsche diesem Abschaum eine gute Reise. Und meinen Beifall an Euch, mein Freund! Ihr habt nicht nur den Familien der Toten den Seelenfrieden gebracht, den sie verdienen, sondern auch eine klare Botschaft an diese korrupten Bürokraten im Oberhaus geschickt. Stormwind muss sich der Probleme der Leute aus dem Dämmerwald annehmen, oder wir werden uns von ihrer Tyrannei befreien." }, enUS = { progress = "So long as a molester of the dead like Dextren Ward is permitted to live, justice stands betrayed.  Return to me once Lord Ebonlocke's sentence of death is carried out on that defiler, Ward.  We shall give the families of the dead the closure they deserve and better yet, we will send a clear message to the House of Nobles in Stormwind.", completion = "So Dextren Ward finally paid for his crimes against humanity?  Good riddance to the scum I say.  And cheers to you, my friend!  Not only have you given the families of the dead the peace of mind they deserve, you sent a poignant message to those corrupt bureaucrats in the House of Nobles.  Stormwind must rise to the needs of the people of Duskwood or we will break free from their tyranny." } })
apply(378, { "classic", "forever" }, { deDE = { progress = "Ich werde nicht zulassen, dass närrische Menschen-Bürokratie zwergischen Angelegenheiten in die Quere kommt, {name}. Kam Deepfury ist erwiesenermaßen einer der Verschwörer des Angriffs auf den Thandol-Übergang. König Magnis gute Gefolgsleute ließen dank Deepfurys Verrat ihr Leben. Den Menschen mag es genug sein, Deepfury im Verlies verrotten zu lassen, aber ich werde nicht mehr ruhig schlafen, bis Deepfury erschlagen ist.", completion = "Kam Deepfury hat also endlich herausgefunden, wie es ist, den Tod selbst zu erfahren? Gut. Geschieht dem feigen Dunkeleisenabschaum recht. Ihr habt Eure Sache gut gemacht, {class}. Die Gefallenen des Angriffs auf den Thandol-Übergang waren nur Opfer in einer Welt voller Krieg und Unfrieden. Ihre Familien werden Frieden in dem Wissen finden, dass Deepfury die Strafe erhielt, die er verdiente. Der Tod von Longbraids Bruder wurde gerächt." }, enUS = { progress = "I won't let foolish Human bureaucracy interfere with Dwarven matters, {name}.  Kam Deepfury is a proven conspirator in the Thandol Span attack.  King Magni's good people lost their lives because of Deepfury's deceit.  The Humans might be content to let Deepfury rot in The Stockade but I will not sleep soundly at night until Deepfury is slain.", completion = "So Kam Deepfury finally got to feel what it is like to be on the receiving end of Death?  Good.  Serves the cowardly Dark Iron scum right.  You have done well, {class}.  The victims of the Thandol Span attack were but mere victims in a world torn with war and unrest.  Their families will have the peace of knowing Deepfury got the punishment he deserved.  Longbraid's brother's death has been avenged." } })
apply(379, { "classic", "forever" }, { deDE = { progress = "Na, haben die Nomanden Euch die Wasserbeutel \"freiwillig\" gegeben?", completion = "Hervorragend, die Kraftquelle gehört Euch. Vorsicht, sie wurde nicht für die Verwendung mit wissenschaftlichen Geräten wie diesen entwickelt. Ihr habt also nur begrenzt Zeit, bevor die von Euch gesammelten Daten auf Nimmerwiedersehen verschwinden!\n\nWenn Ihr alles gesammelt habt, was für das, was auch immer es sei, nötig ist, dann bringt sie zu mir und ich werde sie richtig ausschalten. Ihr habt höchstens zwei Stunden Zeit, um alles zu erledigen, was Ihr vorhabt.\n\nFalls Ihr es in dieser Zeit nicht schafft, kann ich Euch aber eine weitere Kraftquelle für einen neuen Versuch verkaufen. Ihr habt richtig gehört - \"verkaufen\"!" }, enUS = { progress = "Well, did the nomads \"volunteer\" up those water pouches for you?", completion = "Excellent, the power source is yours.  Now, it isn't completely designed for use in a science kit like that, so you'll only have a limited amount of time before all the data you collect will go kablooey!\n\nWhen you collect everything you need for whatever it is you are doing, bring it to me and I'll shut it down properly.  You'll have at most two hours to get what you need to get done, done.\n\nIf you don't get it done in time, I can always sell you another power source to try again.  You heard me - sell!" } })
apply(380, { "classic", "forever" }, { deDE = { progress = "Hütet Euch vor dem Gift dieser Spinnen, {name}. Wenn Ihr ein scharfes Brennen verspürt, solltet Ihr vielleicht jemanden danach sehen lassen.", completion = "Hmm, nun ja, es ist ein Anfang. Es wird ein paar Wochen oder Monate dauern, das Ungeziefer gänzlich auszumerzen. Danach müssen wir mit ein paar Fackeln da runtergehen und die Netze niederbrennen.\n\nIhr habt Eure Pflicht gut erfüllt, {name}, und ich bin mir sicher, ich finde noch etwas anderes für Euch zu tun." }, enUS = { progress = "Be wary of the spiders' venom, {name}. If you feel a sharp burning, you may want to have it looked at.", completion = "Hmm, well, it's a start. It'll take a few weeks or months to fully clean out the infestation. After that, we'll have to get down there with some torches to burn away the webbing.\n\nYou've done your duty well, {name}, I'm sure I can find something else for you to do." } })
apply(381, { "classic", "forever" }, { deDE = { progress = "Diese Narren... Sie schaufeln sich fröhlich ihre eigenen Gräber.", completion = "Wenn sie nur auf die Stimme der Vernunft hören würden, hm, {name}? Vielleicht könnten wir sie dazu bringen, sich mit uns zu einem vernünftigen Gespräch zusammenzusetzen... ha!\n\nVom Licht geblendete Narren." }, enUS = { progress = "Those fools... They happily send themselves to their own graves.", completion = "If only they listened to reason, eh, {name}? Perhaps we could sit them down for reasonable discourse... ha!\n\nLight-blinded fools." } })
apply(382, { "classic", "forever" }, { deDE = { progress = "Wie läuft es mit Eurem Auftrag, {name}?", completion = "Hmmm... Mal sehen, was Ihr da habt... \n\n<Er fängt an, die von Euch beschafften Dokumente durchzublättern.>\n\nNachrichten von ihren Aktionen gegen uns... Wertlos. Spähberichte... Neue Befehle wie \"Baut das Lager nahe der verfallenen Stadt weiter auf...\". Nichts, was wir nicht bereits wüssten... Ah... was haben wir denn hier? Eine Karte, auf der die derzeitigen Posten einiger ihrer Kommandanten und Agenten verzeichnet sind. Damit lässt sich etwas anfangen." }, enUS = { progress = "How goes your mission, {name}?", completion = "Hmm... Let's see what you've got...\n\n<He begins to rifle through the documents you recovered.>\n\nSome news of their exploits against us... Worthless. Scouting reports... New orders, \"Continue to build up a camp near the ruined city...\" Nothing we didn't know already... Ah, what's this? A map of the dispositions of some of their field commanders and agents! We can use this." } })
apply(383, { "classic", "forever" }, { deDE = { progress = "Ja, was wollt Ihr?", completion = "Ja, das ist sehr gut. Diese Informationen zu beschaffen, war gute Arbeit, {name}. Hmm... Die Namen der Offiziere in Tirisfal... \n\nStellt Euch nur vor, welchen Schlag wir der Moral dieser verfluchten Fanatiker verpassen könnten, wenn wir es schaffen, all ihre Anführer auf einen Schlag zu töten." }, enUS = { progress = "Yes, what do you want?", completion = "Yes, this is very good. You've done well in obtaining this information, {name}. Hmm... names of the officers in the Tirisfal Glades...\n\nImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike." } })
apply(384, { "classic", "forever" }, { deDE = { progress = "Ich werde sechs Klippeneberrippchen und einen Krug Rhapsody-Malzbier benötigen, {name}.", completion = "Das Malzbier ist gebraut, die Wildschweine sind abgestochen\nDoch bevor das letzte Wort gesprochen\nWerden wir um dieses leckere Essen\nDer Eberrippchen in Biersauce\nUns erst im Kampfe messen!" }, enUS = { progress = "I'm going to need six crag boar ribs and a mug of Rhapsody Malt, {name}.", completion = "The Malt is brewed, the Boars are dead\nAnd before all is done and anything said\nWe will have to fight for first dibs\nOn these savory Beer Basted Boar Ribs!" } })
apply(385, { "classic", "forever" }, { deDE = { progress = "Hab ich Euch eigentlich erzählt, wie ich damals beinahe meine Hand an einen der Kroks verloren hätte? Ein übles Viech war das, mit Zähnen wie Messer. Aber ich hatte Glück... Hab dem Monster mit meinem Messer das Maul gestopft. Ich habe das Messer sogar noch irgendwo herumliegen...", completion = "Na, wenn das nicht ein paar Prachtexemplare sind, die Ihr da gesammelt habt, {name}. Für hochwertiges Material gibt es selbstverständlich auch eine ordentliche Bezahlung." }, enUS = { progress = "Did I tell you about the time I almost lost my hand to one of the crocs? Nasty bugger it was, teeth like knives. But I was lucky... Jammed the brute's jaw shut with my knife. Still have the knife around here somewhere...", completion = "Well now, these are excellent specimens you collected, {name}. Good money for high quality materials, that's for sure." } })
apply(386, { "classic", "forever" }, { deDE = { progress = "Wart Ihr bereits in Stormwind, im Verlies? Ich fürchte, dass das falsche Spiel, das Targorr den Schrecklichen so lange am Leben erhalten hat, ihm irgendwann seine Freiheit wiederbringen wird. Er wurde zum Tode verurteilt, {name}, nicht dazu, als Schachfigur in den politischen Plänen irgendeines Adeligen missbraucht zu werden.", completion = "Targorr den Schrecklichen hat endlich sein Schicksal ereilt. Es freut mich jedenfalls, zu hören, dass diese Bestie jetzt weiß, wie es ist, selbst im ewigen Griff des Todes zu stecken. Ihr habt Eure Sache gut gemacht, {name}. Manchmal kann wahre Gerechtigkeit nur außerhalb des Gerichtssaales und der Kurzsichtigkeit der Politik gefunden werden." }, enUS = { progress = "Have you been to Stormwind yet, to The Stockade?  I fear whatever trickery that has kept Targorr the Dread alive for this long will eventually bring about his freedom.  He was sentenced to die, {name}, not act as some political pawn on a noble's whim.", completion = "Targorr the Dread has finally met his fate.  I for one am glad to hear the beast now knows what it is like to be on the receiving end of Death's ruthless grip.  You have done well, {name}.  Sometimes the truest justice can only be found outside the courtroom and beyond the clouded vision of politics." } })
apply(387, { "classic", "forever" }, { deDE = { progress = "Das Verlies ist immer noch besetzt! Diesen Defiasratten muss endlich klargemacht werden, dass ihre Taten nicht toleriert werden. Und jetzt geht wieder da runter und zeigt Stärke!", completion = "Eure Bemühungen im Verlies waren tapfer, {name}. Es ist offensichtlich, dass dieses Problem etwas über unserer beider Fähigkeiten liegt. Aber ihr habt Eure Sache gut gemacht, und dafür bin ich Euch dankbar." }, enUS = { progress = "The Stockade is still overrun!  These Defias Rats must be shown that their actions will not be tolerated.  Now get back down there and show some force!", completion = "Your efforts in The Stockade were valiant, {name}.  It's obvious this problem is bigger than the both of us.  But you have performed well and for that I am thankful." } })
apply(388, { "classic", "forever" }, { deDE = { progress = "Wie ich sehe, seid Ihr wieder zurück, {class}. Habt Ihr bereits 10 rote Wollkopftücher der Defias von diesem Abschaum im Verlies gesammelt?", completion = "Diese Kopfwickel - diese schmutzigen Wahrzeichen der Korruption - sind es also, wofür mein Mac sterben musste? Was für eine Verschwendung. Welch tragisches Opfer. \n\nDoch leider kann ich nicht in die Vergangenheit zurückkehren. Wisset jedoch, {name}, dass Ihr meiner Familie mit Euren Taten Gerechtigkeit verschafft habt." }, enUS = { progress = "I see you are back, {class}.  Have you collected 10 Red Wool Bandanas from those Defias Scum in The Stockade yet?", completion = "So these bandanas -- filthy tokens of corruption -- are what my Mac had to die for?  Such a waste.  Such a tragic sacrifice. \n\nBut alas, I cannot return to the past.  Just know, {name}, that you have brought my family justice through your deeds." } })
apply(389, { "classic", "forever" }, { deDE = { completion = "Was, beim Licht, wollt Ihr? Könnt Ihr nicht sehen, dass wir hier in einer Krisensituation sind?\n\nBazil Thredd?! Warum solltet Ihr mit diesem Bastard sprechen wollen? Woher soll ich wissen, ob Ihr nicht einer seiner Spießgesellen seid, der herkam, um ihm bei seinem verdammten Aufstand zu helfen? Wenn die verfluchten Zellen nicht alle offen wären, würde ich Euch für eine Weile in eine davon werfen!" }, enUS = { completion = "What in the Light do you want? Can't you see we have a crisis here?\n\nBazil Thredd?! Why would you want to speak with that bastard? How am I supposed to know you're not one of his cronies, come down to help with his bloody riot? If all the blasted cells weren't open, I might throw you in one for a while!" } })
apply(391, { "classic", "forever" }, { deDE = { progress = "Entweder bringt Ihr mir Thredds Kopf oder ich nehme mir den Euren, kapiert, {name}?", completion = "Jetzt, wo Thredd sie nicht mehr anführen kann, ist der Aufstand hoffentlich eher unter Kontrolle zu bringen... Wir werden sehen.\n\nIch muss gestehen, dass ich nach einer halben Stunde kaum mehr erwartete, dass Ihr wieder herauskommen würdet, aber ich habe Euch wohl falsch eingeschätzt.\n\nIch nehme daher mal an, dass Ihr nicht viele nützliche Informationen aus ihm herausbekommen habt. Aber ich weiß bereits das eine oder andere über Thredds Aktivitäten, das für Euch von Interesse sein könnte." }, enUS = { progress = "Either you bring me Thredd's head, or I'll take yours, understand, {name}?", completion = "Without Thredd to lead them, hopefully the riots will be more controllable. We shall see.\n\nI must say, after a half hour, I hardly expected you to come out, but it seems I misjudged you.\n\nI'd guess, then, that you didn't get much useful information out of him? But I know a thing or two that might be of interest to you about Thredd's activities." } })
apply(392, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Was habt Ihr gefunden?", completion = "Hmm. Maelik? Nein, der Name sagt mir nichts und auch nicht diese Beschreibung. Aber es könnte ein jeder sein! Ein früherer Steinmetz, einer von der Bruderschaft der Defias... Wenn er allerdings tatsächlich so viele Verbindungen hat, wie Thelwater andeutet, dann erkennt ihn vielleicht jemand anderes. Lasst mich nachdenken." }, enUS = { progress = "Yes, {name}? What have you found?", completion = "Hmm. Maelik? No, the name doesn't sound familiar and neither does this description. But it could be anybody! A former Stonemason, one of the Defias Brotherhood... Though if he is as well connected as Thelwater suggests, perhaps someone else might recognize him. Let me think." } })
apply(393, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt. Wie kann ich Euch zu Diensten sein, {class}?", completion = "Was? Was ist das? Ja, ich glaube, ich weiß, wer dieser Mann ist, aber sein Name ist nicht Maelik. Auftragsmörder tragen viele Namen und viele Masken und lassen sie hinter sich, sobald sie ihren Nutzen verloren haben. Ein anderer Name, den dieser Mann benutzt, ist Marzon, obwohl auch das sicherlich nicht sein wirklicher Name ist.\n\nNichtsdestotrotz ist er ein Auftragsmörder, und ich weiß eine ganze Menge über ihn.\n\nMarzon arbeitet derzeit für Lord Gregor Lescovar, einen Lord mit zweifelhaftem Ruf, selbst gemessen am korrupten Adel von Stormwind." }, enUS = { progress = "Greetings. Of what service can I be to you, {class}?", completion = "What? What's this? Yes, I think I do know who this man is, but his name is not Maelik. Assassins wear many names and many masks, discarding them as they lose their usefulness. Another alias known to be used by this man is Marzon; though even that is surely not his true name.\n\nRegardless, he is an assassin and I know a good deal about him.\n\nMarzon is currently under the employ of Lord Gregor Lescovar, a lord of shady reputation, even given the corruption of the nobility of Stormwind." } })
apply(394, { "classic", "forever" }, { deDE = { completion = "Er ist also tot? Ihr wart schnell mit der Vollstreckung des Urteils, {name}. Ich bete zum Licht, dass ich niemals Euer Ziel sein möge!\n\n\n\nDas war nicht als Kritik zu verstehen, {name}. Wie könnte es auch, wo ich doch der Meister aller Auftragsmörder bin? In Wahrheit habt Ihr den Einwohnern von Stormwind einen großen Dienst erwiesen und dafür danke ich Euch." }, enUS = { completion = "He is dead, then? Your justice was swift, {name}. I pray to the Light that I never become your quarry!\n\n\n\nI mean no criticism, {name}. How could I, being the master of all assassins? But in truth, you have done the people of Stormwind a great service, and for that, I thank you." } })
apply(395, { "classic", "forever" }, { deDE = { completion = "Es ist schön, Euch zu sehen, {name}. Wie ich hörte, wurde Lord Gregor Lescovar vor kurzem tot aufgefunden.\n\nEs sieht also so aus, als wäret Ihr mit Eurer Mission erfolgreich gewesen. Ihr könnt Euch meines Dankes dafür gewiss sein, dass Ihr mich und viele andere vor van Cleefs Rache bewahrt habt." }, enUS = { completion = "It's good to see you, {name}. I have heard that Lord Gregor Lescovar was found dead not long ago.\n\nIt would seem that you were successful in your mission. You have my gratitude that you have saved me, and many others, from VanCleef's revenge." } })
apply(397, { "classic", "forever" }, { deDE = { completion = "Meister sagt, gib {name} Geschenk. Zggi will schönes Geschenk behalten, aber Zggi zu klug, Meister zu verraten." }, enUS = { completion = "Master says give gift to {name}.  Zggi wants to keep nice gift but Zggi knows better than to betray Master." } })
apply(398, { "classic", "forever" }, { deDE = { progress = "Ja?", completion = "Madenauges abscheuliche Taten wurden endlich gerächt. Vielleicht sind Eure mutigen Taten eine klare Botschaft an die, die unserem Volk Leid zufügen wollen. Ich danke Euch im Namen der Stadt Brill, {name}." }, enUS = { progress = "Yes?", completion = "Maggot Eye's dastardly acts have finally been avenged.  Maybe your acts of valor will send a clear message to those who wish to bring harm to our people.  On behalf of the town of Brill I thank you, {name}." } })
apply(399, { "classic", "forever" }, { deDE = { progress = "{name}! Hattet Ihr Glück?", completion = "Oh, ich danke Euch, {name}! Er hat zwar keinen praktischen Nutzen für mich, aber sein sentimentaler Wert... Ich muss wohl nicht betonen, wie dankbar ich bin, dass Ihr mir dies zurückgebracht habt... unter Einsatz Eures Lebens, ganz zu schweigen von der Zeit, die der lange Weg bis hinunter nach Westfall in Anspruch nahm. Habt Dank, und nehmt dies als ein Zeichen meiner Anerkennung." }, enUS = { progress = "{name}! Did you have any luck?", completion = "Oh, thank you, {name}! It's of no practical use to me, but the sentimental value... Needless to say, thank you for bringing this to me... at some cost to your own well-being, not to mention the time it took to go all the way down to Westfall. You have my gratitude, and have this as a token of my thanks." } })
apply(400, { "classic", "forever" }, { deDE = { progress = "Hm? Ihr seht etwas zu jung aus für einen Piloten der Belagerungsmaschinen. Aber egal... Braucht Ihr eine Reparatur?\n\nDann zieht eine Nummer und macht es Euch bequem. Ich arbeite gerade an ein paar Maschinen und werde wenigstens einige Tage lang keine Zeit für weitere Aufträge haben.\n\nOder seid Ihr wegen etwas anderem hier... ?", completion = "Ihr habt meine Werkzeuge? Gut gemacht, Junge, gut gemacht! Ich habe gerade vor einer Stunde meine letzte Zahnratsche zerbrochen, und ich brauche eine, um die Reparatur an Pilot Stonegears Belagerungsmaschine abzuschließen. Gut, dass Ihr diese Werkzeuge hierher geschafft habt, {name}.\n\nHier, nehmt diese Münzen, für Eure Hilfe." }, enUS = { progress = "Hm?  You look a little young to be a siege engine pilot.  But no matter...do you need something fixed?\n\nWell take a number and get comfortable.  I'm working on a couple engines right now and won't have time for another job for at least a few days.\n\nOr, were you here for something else...?", completion = "You have my tools?  Well done, lad, well done!  I just broke my last fang-ratchet an hour ago and I need one of those to finish repairs on Pilot Stonegear's siege engine.  You did a good thing by lugging those tools here, {name}.\n\nHere, take these coins for your help." } })
apply(401, { "classic", "forever" }, { deDE = { completion = "So, hier haben wir's. Übersetzt heißt es... \n\n<Die Luft wird schwerer, als würde sich ein dicker, schwarzer Mantel über das Land legen... >" }, enUS = { completion = "There we are.  It's translated...\n\n<The air grows heavy, as if a thick, black curtain is drawn over the land...>" } })
apply(404, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Aufgabe erledigt, die ich Euch auftrug? Habt Ihr die eitrigen Klauen?", completion = "Gut gemacht. Schade, dass ich nicht dabei war, um Euch zuzusehen, wie Ihr diese Untoten zu Brei geschlagen habt." }, enUS = { progress = "Have you completed the task with which I have charged you?  Do you have those putrid claws?", completion = "Well done.  I regret not being there to see you smash those {race} into rotting pulp!" } })
apply(405, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt. Entweder wisst Ihr nicht, wer ich bin, oder Ihr habt dringliche Geschäfte mit mir zu erledigen.\n\nDenn würde beides nicht zutreffen, wärt Ihr nicht töricht genug, mich zu stören...", completion = "Ah, Ihr seid der Agent, den Magistrat Sevren schickt. Also sind Eure Geschäfte mit mir tatsächlich wichtig.\n\nIch gehe davon aus, dass Sevren jemanden ausgewählt hat, der meiner Aufgabe gewachsen ist... aber wir werden sehen." }, enUS = { progress = "Greetings.  Either you do not know who I am, or your business with me is urgent.\n\nBecause if neither of these were true, then you would not be foolish enough to disturb me...", completion = "Ah, you are the agent sent by Magistrate Sevren.  Then yes, your business with me is crucial.\n\nI trust Sevren has mustered someone suitable for my task...but we shall see." } })
apply(407, { "classic", "forever" }, { deDE = { progress = "Bleibt mir vom Leibe, bösartige und unheilige Kreatur! Möge das Licht mich beschützen! Der Scharlachrote Kreuzzug wird Azeroth von Eurer... \n\n... oh, Moment mal. Ist das etwas zu essen für mich? Ich bin so was von hungrig...", completion = "Beim Licht! Endlich etwas zu essen! Süßer, leckerer Kürbis..." }, enUS = { progress = "Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your. . .\n\n. . .oh wait.  Is that food for me?  I am so hungry. . .", completion = "By the Light!  Finally some food!  Sweet, sweet pumpkin. . . ." } })
apply(408, { "classic", "forever" }, { deDE = { progress = "Zeit ist ein Luxus, den wir uns nicht leisten können, {name}. Mit jeder Stunde, die verstreicht, festigt sich der Griff der Geißel um Tirisfal.", completion = "Eure Taten verpassten der Geißel einen merklichen Schlag. Und Euer Sieg wird nicht unbemerkt bleiben - weder von den Verlassenen, noch von unseren Feinden.\n\nKämpft weiter, wie wir alle, {name}, und eines Tages werden wir den Lichkönig daselbst aus Azeroth vertreiben!" }, enUS = { progress = "Time is not a luxury we have, {name}.  With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", completion = "Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.\n\nContinue the struggle as we all do, {name}, and one day we will drive the Lich King himself from Azeroth!" } })
apply(409, { "classic", "forever" }, { deDE = { completion = "Ihr habt Lillith Nefara getötet und damit bewiesen, dass Ihr ein Feind der Geißel seid. Unglaublich.\n\nIch glaubte, der einzige Untote mit freiem Willen zu sein, aber Ihr habt mir gezeigt, dass es andere gibt, die der Kontrolle des Lichkönigs getrotzt haben." }, enUS = { completion = "You have defeated Lillith Nefara, proving you are an enemy of the Scourge.  Incredible.\n\nI had believed I was the only {race} with free will, but you have shown me there are others who have broken the Lich King's domination." } })
apply(411, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Gunthers Buch zurückgebracht? Hat er geantwortet?", completion = "Ihr habt ihn dazu gebracht, sich uns anzuschließen! Ihr habt den Verlassenen einen großen Dienst erwiesen, {name}. Die dunkle Fürstin wird das erfahren." }, enUS = { progress = "Have you returned Gunther's book?  Has he responded?", completion = "You convinced him to join us!  You have done a great deed for the Forsaken, {name}.  The Dark Lady will be informed." } })
apply(412, { "classic", "forever" }, { deDE = { progress = "Der Rekombobulator wird laufen wie geschmiert, sobald wir ausreichend Restabilisationszahnräder und gyromechanische Getriebeteile haben.", completion = "Diese gyromechanischen Getriebeteile und Restabilisationszahnräder stimmen genau mit Ozzies Bauplan für das Rekombobulationsgerät überein. Sobald ich jetzt etwas Hydroschmiermittel auf die inneren Verbrennungskolben gebe, die Kurbelratsche justiere und die Zähflüssigkeit des Electrogumgels erhöhe, wird das gnomische Volk wieder wie neu sein." }, enUS = { progress = "The Recombobulator will be up and running as soon as we have sufficient Restabilization Cogs and Gyromechanic Gears.", completion = "These Gyromechanic Gears and Restabilization Cogs are in perfect accordance with Ozzie's schematics for the Recombobulation Device.  Once I add some hydrolubricant to the inner combustion pistons, adjust the crank-o-ratchet and increase of the viscosity of the electrogum gel, the gnomish race will be as good as new." } })
apply(413, { "classic", "forever" }, { deDE = { progress = "Hallo, {class}! Na, welche Geschäfte treiben Euch den weiten Weg bis nach hier draußen?\n\nHoffentlich etwas Aufregendes. Ich hatte seit Tagen keinen ordentlichen Kampf mehr, und dieses Fass Bier ist so gut wie leer...", completion = "<Gebirgsjäger Gerstenbräu probiert das Schimmerstarkbier... >\n\nOh, wow! Dieses Zeug treibt einem wirklich Glanz in die Augen. Ich fühle mich, als könnte ich im Dunkeln sehen!" }, enUS = { progress = "Hello, {class}!  And what business takes you all the way out here?\n\nSomething exciting, I hope.  I haven't been in a good fight in days, and this barrel of ale is almost dry...", completion = "<Mountaineer Barleybrew tastes the Shimmer Stout...>\n\nOh.  Whoa!  This stuff really puts a shine in your eyes.  I feel like I can see in the dark!" } })
apply(414, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}, und willkommen in Thelsamar!", completion = "Und jetzt lasst mich mal versuchen... \n\nBeim Barte Magnis! Dieses Zeug haut einem die Birne weg! Und macht dabei die Gliedmaßen so leicht.\n\nIch fühle mich, als könnte ich fliegen!" }, enUS = { progress = "Greetings, {class}, and welcome to Thelsamar!", completion = "Now, let me have a taste...\n\nMagni's Beard!  This stuff gets your head turning!  And it lightens the limbs, too.\n\nI feel like I can fly!" } })
apply(415, { "classic", "forever" }, { deDE = { completion = "{name}! Erinnert Ihr Euch an das Schimmerkraut, das Ihr mir gebracht habt? Nun, ich habe es in einigen der Rezepte, an denen ich zuletzt gearbeitet habe, ausprobiert, und eines davon gelang einfach großartig!\n\nHier, versucht es und sagt mir, was Ihr davon haltet..." }, enUS = { completion = "{name}!  You know that Shimmerweed you brought me?  Well I used it in a few recipes I've been working on, and one of them turned out great!\n\nHere, try it out and tell me what you think..." } })
apply(416, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Wie steht es mit der Rattenjagd?", completion = "Igitt! Als ich diese Ohren verlangte, hatte ich keine Ahnung, dass sie so schrecklich stinken würden.\n\nHier ist Eure Belohnung, {name}. Gut gemacht." }, enUS = { progress = "Hail, {name}.  How goes the rat catching?", completion = "Ugh!  When I asked for those ears I didn't realize they'd smell so bad!\n\nHere's your reward, {name}.  Well done." } })
apply(417, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Wisst Ihr etwas über den Verbleib meines Freundes Hildelve?", completion = "Das sind traurige Neuigkeiten, denn Hildelve war ein guter Freund. Ich wünschte, ich hätte dort mit Euch sein können, als Ihr die Bestie Marterklaue gefunden habt!\n\nDanke, {name}. Eure Tat wird den Piloten der Belagerungsbrigade von Ironforge in Erinnerung bleiben." }, enUS = { progress = "Hello, {name}.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, {name}.  Your deed will be remembered by the pilots of the Ironforge Siege Brigade." } })
apply(418, { "classic", "forever" }, { deDE = { progress = "Ich bin so weit, dass ich mit dem Kochen anfangen könnte; habt Ihr die Zutaten?", completion = "Vertraut mir, es ist schwerer als es aussieht, aber... \n\nAch, ich habe bisher noch nie jemanden getroffen, der sich sehr für die Herstellung von Würsten interessiert hat, aber ich werde Euch für alle Fälle dennoch das Rezept geben. Hier, und denkt immer daran, sie zu essen, solange sie frisch sind!" }, enUS = { progress = "I'm all ready to start cooking, do you have the ingredients for me?", completion = "Trust me, it seems a lot harder than it looks, but...\n\nOh, I've never known someone to take much interest in the making of sausages, but I'll give you the recipe just in case. Here you go, mind you eat them fresh!" } })
apply(419, { "classic", "forever" }, { deDE = { completion = "Hier liegt die Leiche eines Zwergs - zerfetzt, gefroren und von Aasfressern blankgefressen. Seine Hand umklammert ein Buch, das die grob hingekritzelten Aufzeichnungen von Mori Hildelve enthält. Um ihn gehüllt, nach wie vor in sehr gutem Zustand, ist eine Brigadiersweste.\n\nAn diesem grausigen Ort muss der Pilot der Belagerungsmaschinen sein Ende gefunden haben." }, enUS = { completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end." } })
apply(420, { "classic", "forever" }, { deDE = { progress = "Wie geht es Euch? Wollt Ihr vielleicht etwas mit mir trinken? Es gibt in der Kälte sonst nichts zu tun.", completion = "Was ist das? Ah, der Bericht meines Bruders. Hmm... \n\nIch habe ihm gesagt, er soll den Namen des Königs nur dezent einsetzen, aber er wollte ja nicht auf mich hören. Es kann nicht schaden, schätze ich, aber es werden sich auf alle Fälle einige im Senat die Haare raufen. Nicht, dass die diese Rauferei nicht mal nötig hätten! Ha!\n\nNichtsdestotrotz heißt das wohl, dass ich meinen Bericht ebenfalls nach Ironforge schicken sollte, aber ich muss zugeben, dass ich etwas im Rückstand bin. Verdammte Kälte.\n\nIch dürfte später etwas Arbeit für Euch haben, wenn Ihr Interesse habt." }, enUS = { progress = "How are you? Like to share a drink with me, perhaps? Not much else to do in the cold.", completion = "What's this? Ah, my brother's report. Hmm...\n\nI told him to be sparing with the use of the King's name, but he didn't listen. No harm, I suppose, though it's sure to ruffle some feathers in the Senate. Not that those weren't some feathers that needed ruffling! Hah!\n\nNonetheless, I guess that means that I should send my report on to Ironforge as well, but I must admit I'm a bit behind. Bloody cold.\n\nI should have some work for you later, if you're interested." } })
apply(421, { "classic", "forever" }, { deDE = { completion = "Ihr habt mir gut gedient, {class}. Mir ist klar, dass Ihr mir eine wertvolle Hilfe sein werdet, wenn ich beginne, den Silberwald von Arugals Fluch zu befreien." }, enUS = { completion = "You have served me well, {class}.  It is obvious to me that you will be a worthy aide to me as I prepare to rid Silverpine Forest of Arugal's curse." } })
apply(422, { "classic", "forever" }, { deDE = { progress = "Bevor ich weiß, womit wir es hier genau zu tun haben, {class}, muss ich den Zauber untersuchen, der als 'Arznei des Arugal' bekannt ist. Bringt ihn mir umgehend, oder ich bin gezwungen, mir einen geeigneteren Diener zu suchen.", completion = "Das ist genau der Zauber, den ich suchte, {class}. Wenn Eure Hingabe an die Sache der dunklen Fürstin weiterhin so ungetrübt bleibt, werdet Ihr eine große Zukunft unter den Verlassenen haben." }, enUS = { progress = "Before I know what we are dealing with here, {class}, I need to study the spell known as Remedy of Arugal.  Bring it to me now or I shall be forced to find myself a worthy servant.", completion = "This is precisely the spell I was in search of, {class}.  If your dedication to The Dark Lady's cause remains infallible you will find you have quite a future amongst The Forsaken." } })
apply(423, { "classic", "forever" }, { deDE = { progress = "Ich brauche 6 Nimmersattfesseln und 3 Dunkelseelenfesseln, bevor ich die Situation einschätzen und eine endgültige Lösung für Arugal ersinnen kann. Und jetzt kommt meiner Aufforderung nach und erschlagt Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr habt, was ich brauche.", completion = "Ich hoffe, ich kann aus dieser kleinen Auswahl genug Energie ziehen. Vielleicht hätte ich Euch mehr Fesseln holen lassen sollen.\n\nNichtsdestotrotz habt Ihr großes Geschick darin bewiesen, diese zu sammeln, {class}." }, enUS = { progress = "I will need 6 Glutton Shackles and 3 Darksoul Shackles before I can assess the situation and devise a final solution for Arugal.  Now heed your bidding and slay Moonrage Gluttons and Moonrage Darksouls until you have what I need.", completion = "I hope I can acquire enough energy from such a limited sample.  Perhaps I should have had you get more shackles.\n\nNonetheless, you showed great skill in collecting these, {class}." } })
apply(424, { "classic", "forever" }, { deDE = { progress = "Ist Grimson der Blasse erschlagen? Varimathras wird nicht gerade glücklich sein, wenn wir seine Wünsche ignorieren.", completion = "Wunderbar. Die Mine wird unseren Truppen hervorragende Rohstoffe liefern, wenn wir uns im Silberwald und nach Azeroth hinein ausbreiten." }, enUS = { progress = "Has Grimson the Pale been slain?  Varimathras will not be pleased if we ignore his bidding.", completion = "Most excellent.  The mine will provide superb resources for our forces as we spread throughout Silverpine and into Azeroth." } })
apply(425, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Ivar den Verfaulten getötet? Wenn Ihr es nicht für mich und meinen Bruder tun wollt, dann tut es für die Verlassenen.", completion = "Ah, habt Dank. Ihr habt meine Anerkennung, {name}.\n\nUnd ich werde Euch in dem Bericht an meine Vorgesetzten erwähnen." }, enUS = { progress = "Have you killed Ivar the Foul?  If you won't do it for me and my brother, then do it for the Forsaken.", completion = "Ah, thank you.  You have my gratitude, {name}.\n\nAnd I will include you in the report I make to my superiors." } })
apply(426, { "classic", "forever" }, { deDE = { progress = "Unser Krieg gegen die Geißel dauert noch immer an, {name}. Tut das Eurige und werft diese verfluchten, hirnlosen Untoten wieder zurück in die Pestländer!", completion = "Eure Bemühungen im Krieg sind spürbar, {name}. Ich werde Euch nicht für etwas Notwendiges danken, aber die Todeswachen von Tirisfal werden sich Eures Namens erinnern." }, enUS = { progress = "Our battles with the Scourge wage on, {name}.  Do your part and throw those cursed, mindless {race} back into the Plaguelands!", completion = "Your efforts in the war are felt among us, {name}.  I will not thank you for doing what is necessary, but the Deathguards of Tirisfal will remember your name." } })
apply(427, { "classic", "forever" }, { deDE = { completion = "Wunderbar, {class}. Euer Geschick in der Kriegskunst ist nicht zu leugnen." }, enUS = { completion = "Most excellent, {class}.  Your skill in the art of combat is undeniable." } })
apply(428, { "classic", "forever" }, { deDE = { completion = "Ihr habt uns gefunden! Und das keinen Moment zu früh..." }, enUS = { completion = "You found us!  And not a moment too soon..." } })
apply(429, { "classic", "forever" }, { deDE = { progress = "Meine Zeit ist knapp, {class}, denn die dunkle Fürstin hat mich mit einer wichtigen Aufgabe betraut.", completion = "<Renferrel nimmt die Herzen entgegen.>\n\nEs ist beunruhigend zu hören, dass unsere Todespirscher ihren Auftrag nicht erfüllt haben.\n\nHoffen wir, dass solche Fehlschläge die Ausnahme sind.\n\nIch werde Euch den Trank gleich geben, aber hier habt Ihr erst einmal sein Rezept - falls diese Todespirscher wieder einmal Hilfe benötigen, könnt Ihr sie ihnen vielleicht selbst verabreichen." }, enUS = { progress = "My time is short, {class}, for the Dark Lady has charged me with a grave task.", completion = "<Renferrel takes the hearts.>\n\nIt is troubling to hear our Deathstalkers have failed their mission.\n\nLet us hope that these failures are rare.\n\nI'll give you the potion in a moment, but here is its recipe - if those Deathstalkers find themselves in need of future aid, then perhaps you can give it yourself." } })
apply(430, { "classic", "forever" }, { deDE = { progress = "Meine Schwester sagte mir, Ihr wäret hier, um uns zu helfen. Stimmt das?", completion = "<Quinn nimmt den Trank und trinkt ihn.>\n\nJa, ich kann spüren, wie er wirkt. Ich werde bald wieder reisen können.\n\nIhr habt mir einen großen Gefallen getan, {name}." }, enUS = { progress = "My sister told me you were here to aid us.  Is that true?", completion = "<Quinn takes the potion and drinks it.>\n\nYes, I can feel it working.  I will soon be able to travel.\n\nYou have done me a great favor, {name}." } })
apply(432, { "classic", "forever" }, { deDE = { progress = "Das macht mich dermaßen wütend! Grrr...", completion = "Nun, jetzt geht es mir schon etwas besser... \n\nAber ich werde mich erst wieder richtig freuen können, wenn sie alle tot sind! Restlos alle!" }, enUS = { progress = "It makes me so mad! Grrr...", completion = "Well, that makes me feel a little better...\n\nBut I won't be happy until they're all dead! All of them!" } })
apply(433, { "classic", "forever" }, { deDE = { progress = "Wenn wir die Troggs vom Gol'Bolar Steinbruch entfernen können, wäre das der Erste von vielen Schritten, die wir unternehmen müssen, um uns von dieser Bedrohung zu befreien.", completion = "Das ist ein Anfang. Hoffentlich können wir ihn nutzen und einige Gebirgsjäger hineinschicken, um das Gebiet zu sichern. Dann können wir damit anfangen, unsere Infrastruktur wieder aufzubauen und unsere Minenarbeiter wieder an die Arbeit schicken.\n\nDanke für Eure Unterstützung, {name}." }, enUS = { progress = "If we can remove the troggs from Gol'Bolar quarry, it will be the first step of many that we will have to undertake to rid ourselves of this menace.", completion = "It is a start. Hopefully we can take advantage of it, and move some Mountaineers in to secure the area. Then we can begin to restore our infrastructure and get the miners back to work.\n\nThank you for your assistance, {name}." } })
apply(434, { "classic", "forever" }, { deDE = { completion = "Es ist also vollbracht? Gut. Ich danke Euch vielmals für Eure Diskretion, {name}. Ihr habt Euch in mehr als einer Hinsicht als würdig erwiesen. Ich werde Euch und Euren Aufstieg innerhalb der Allianz ganz bestimmt im Auge behalten.\n\nAchtet darauf, dass Ihr Eure Finger nicht schmutzig macht." }, enUS = { completion = "So it is done? Good. Thank you greatly for your discretion, {name}. You've proven worthy on more than one count. I'll be sure to keep my eyes on you and your progress within the Alliance.\n\nBe sure to keep your nose clean." } })
apply(435, { "classic", "forever" }, { deDE = { completion = "Danke für die Hilfe, {name}. Ich hatte befürchtet, Erland wäre den Gefahren des Silberwaldes erlegen. Aber dank Eurer Hilfe war dem offensichtlich nicht so." }, enUS = { completion = "Thank you for the aid, {name}.  I had feared Erland was overcome by the dangers of Silverpine.  With your help, I see that he has not." } })
apply(436, { "classic", "forever" }, { deDE = { completion = "Jern will wissen, was uns aufhält, hm?\n\nIronband verfasst gerade seinen jüngsten Fortschrittsbericht mit allen Details, aber ich kann Euch Folgendes sagen:\n\nEs sind die Troggs!" }, enUS = { completion = "Jern wants to know what the slowdown is, eh?\n\nIronband is putting together his latest progress report with details, but I can tell you this:\n\nIt's the Troggs!!" } })
apply(437, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Nachtseele besiegt, {name}? Unser Erfolg im Kampf gegen die Moderfelle hängt von ihrer Vernichtung ab!", completion = "Ich habe von Eurem erfolgreichen Überfall auf die Moderfellgnolle gehört, {name}, und diese Essenz ist der Beweis für Nachtseeles Tod.\n\nDie Geißel hat heute an Boden verloren. Euer Ansehen bei den Verlassenen ist gestiegen." }, enUS = { progress = "Have you defeated Nightlash, {name}?  Our success against the rot hides depends on her destruction!", completion = "I heard of your successful raid against the rot hides, {name}, and this essence is proof of Nightlash's death.\n\nThe Scourge have lost ground this day.  Your value to the Forsaken grows." } })
apply(438, { "classic", "forever" }, { deDE = { completion = "In diesem Boot ist ein Haufen eingewickelter Leichen aufgestapelt. Und wenn man nach Osten über den Lordameresee schaut, kann man gegenüber auf der Insel Fenris ein Dock sehen.\n\nDas Schicksal muss diese Toten auf der Insel Fenris ereilt haben." }, enUS = { completion = "Heaped within this boat is a pile of wrapped corpses.  And looking east across Lordamere Lake, an opposing dock on Fenris Isle can be seen.\n\nThe fate of the corpses must lie on Fenris Isle." } })
apply(439, { "classic", "forever" }, { deDE = { progress = "{name}. Ihr kehrt zurück; darf ich also annehmen, dass Eure Nachforschungen Früchte trugen?", completion = "Ihr sagt, dieser Ring wurde von einer erst kürzlich getöteten Frau getragen?\n\nDie einzige nahe gelegene Quelle für solch einen Körper wären die Massengräber in Tirisfal. Die Moderfellgnolle müssen die Leichen wohl zur Insel Fenris bringen!" }, enUS = { progress = "{name}.  You return, so I assume your investigations bore fruit?", completion = "You say that this ring was worn by a woman, recently killed?\n\nThe only nearby source of such a body would be the mass graves in Tirisfal.  The Rot Hide Gnolls must be taking those corpses to Fenris Isle!" } })
apply(440, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Was führt Euch nach Brill zurück?", completion = "Vor nicht allzu langer Zeit lebte in Brill eine Deliah. Sie wurde im Massengrab beigesetzt, aber wenn das, was Ihr sagt, zutrifft, dann müssen die Moderfellgnolle ihre Leiche gestohlen und in den Silberwald gebracht haben.\n\nDie Moderfelle müssen, wie alle Teile der Geißel, vernichtet werden. Ich vertraue darauf, dass Ihr darauf hinarbeitet." }, enUS = { progress = "Hello, {name}.  What brings you back to Brill?", completion = "A Deliah did live in Brill not long ago.  She was buried in the mass grave but if what you say is true, then the Rot Hide Gnolls must have stolen her body and taken it to Silverpine.\n\nThe Rot Hides, like all the Scourge, must be destroyed.  I trust you are taking steps to make that happen." } })
apply(441, { "classic", "forever" }, { deDE = { progress = "Kenne ich Euch?", completion = "Ja, dieser Ring gehörte meiner Frau. Ihr Schicksal war das all derer, die diese harten Zeiten nicht überstehen. Ihr Tod bedeutet mir nichts, genauso wenig wie die Geschichte, die Ihr von der Entwendung ihrer Leiche erzählt.\n\nSolche Gefühle sind vor langer Zeit in mir erloschen. Doch ein Verlangen brennt immer noch in meinem toten Herzen, {name}.\n\nDas Verlangen nach Rache." }, enUS = { progress = "Do I know you?", completion = "Yes, this ring was my wife's.  Her fate was the fate of all who fail to endure these harsh times.  I feel nothing for her death, nor for the story you tell of her body's abduction.\n\nSuch feelings have long since grown cold within me.  But desire does still burn in my dead heart, {name}.\n\nDesire for revenge." } })
apply(442, { "classic", "forever" }, { deDE = { progress = "Der Geißel darf nicht gestattet werden, im Silberwald zu bleiben, {name}. Kommt zu mir zurück, wenn Ihr den Beweis für Thules Tod habt.", completion = "Der Tod von Thule Rabenklaue war kein unwichtiges Ereignis, {name}. Renferrel sagt mir, dass die Energien, die frei wurden, als Ihr Thule vernichtet habt, bis zum Grabmal zu spüren waren.\n\nDie Nachricht von Euren Taten verbreitet sich bei den Verlassenen wie ein Lauffeuer. Euer Wert für uns wächst unaufhörlich." }, enUS = { progress = "The Scourge cannot be allowed to remain in Silverpine, {name}.  Come back to me when you have proof of Thule's death.", completion = "The death of Thule Ravenclaw was no small event, {name}.  Renferrel tells me that the energies released when you destroyed Thule were felt even as far as the Sepulcher.\n\nYour actions ring through the ranks of the Forsaken.  Your value to us grows." } })
apply(443, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Moderfellsekret, {name}?", completion = "Sehr gut. Dieses Sekret wird uns dabei helfen, die Natur der Moderfelle zu verstehen, und könnte uns ihre Schwächen aufzeigen... \n\n... sofern sie welche haben." }, enUS = { progress = "Do you have the rot hide ichor, {name}?", completion = "Very good.  This ichor will help us understand the nature of the rot hides, and may show us their weakness...\n\n...if they have one." } })
apply(444, { "classic", "forever" }, { deDE = { progress = "Meine Studien erfordern große Konzentration. Ich will also hoffen, dass Euer Besuch von Bedeutung ist.", completion = "Diese Substanz ist mit mächtigen Zaubern versetzt, von denen ich einige seit einer langen, langen Zeit nicht mehr gesehen habe... \n\nEinen Moment - ich muss einen Erkenntniszauber sprechen..." }, enUS = { progress = "My studies require great concentration.  So I hope your visit is not a frivolous one.", completion = "This substance is laced with powerful spells, some of which I have not seen for a long, long time...\n\nOne moment -- I must invoke a spell of divination..." } })
apply(445, { "classic", "forever" }, { deDE = { progress = "Was wollt Ihr von mir, {class}?", completion = "Ah, wie zuvorkommend von Apotheker Johaan, mir seine Nachforschungen zu schicken. Dank der ganzen jüngsten Entwicklungen hier im Silberwald hätte ich beinahe die Erkenntnisse vergessen, die aus Lordaeron und Tirisfal kommen. Das erinnert mich daran, dass ich diese Proben umgehend zur Nekropole losschicken muss.\n\nIhr müsst meine Abschweifungen entschuldigen. Verlängert Euren Aufenthalt im Silberwald ein wenig, {name}. Ein kräftiger {class} wie Ihr wäre hier durchaus von Nutzen." }, enUS = { progress = "What business do you have with me, {class}?", completion = "Ah, how good of Apothecary Johaan to send his research.  With so many new developments here in Silverpine, I nearly forgot about the findings coming out of Lordaeron and Tirisfal Glades.  Which reminds me, I need to get those samples off to the Necropolis soon.\n\nBut you must excuse my rambling.  Extend your stay in Silverpine, {name}.  We could use an able bodied {class} like you around here." } })
apply(446, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Was hat Bethor gesagt?", completion = "Diese Schriftrolle ist voll mächtiger Magie. Ich habe noch nie solche Kräfte in einem Trank verwendet... Es wird eine mächtige Mixtur sein und dürfte Euch wertvolle Dienste leisten, wenn Ihr Thule in seiner Festung auf der Insel Fenris angreift." }, enUS = { progress = "Greetings, {name}.  What did Bethor have to say?", completion = "This scroll is laced with powerful magic.  I've never used such forces in a potion ... it will be a powerful mixture, and should serve you well should you attack Thule in his stronghold on Fenris Isle." } })
apply(447, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {class}. Was wollt Ihr von der königlichen Apothekervereinigung?", completion = "Wie gut, dass Apotheker Renferrel Euch zu mir geschickt hat, {name}. Diese Proben werden sich als durchaus nützlich für unsere Zwecke erweisen. Ich werde gleich damit anfangen, ihre toxischen und verseuchenden Eigenschaften zu untersuchen." }, enUS = { progress = "Hail, {class}.  What business do you have with the Royal Apothecary Society?", completion = "How good of Apothecary Renferrel to send you to me, {name}.  These samples will indeed prove useful to the cause.  I will begin studying their toxic and contaminable properties at once." } })
apply(448, { "classic", "forever" }, { deDE = { completion = "Wenn das, was Bethor sagt, wahr ist, dann stellt Thule Rabenklaue eine Macht dar, um die sich jemand kümmern muss, und zwar bald.\n\nUm Euch bei dieser Aufgabe zu helfen, könnt Ihr Euch an unserem Arsenal hier bedienen..." }, enUS = { completion = "If what Bethor says is true then Thule Ravenclaw is a force that must be dealt with, and dealt with soon.\n\nTo aid in this task, you may take something from our arsenal here..." } })
apply(449, { "classic", "forever" }, { deDE = { progress = "Habt Ihr herausgefunden, was den Todespirschern zustieß?", completion = "Ich hatte nicht mit einem solchen Ausmaß an Aktivitäten der Geißel im Silberwald gerechnet, geschweige denn mit den Problemen, die unsere Todespirscher bei ihren Erkundungsversuchen hatten.\n\nEure Hilfe für unsere Todespirscher war unschätzbar, {name}. Dafür erhaltet Ihr eine Belobigung." }, enUS = { progress = "Did you discover the fate of the Deathstalkers?", completion = "I hadn't accounted for the level of Scourge presence we've seen in Silverpine Forest, nor for the troubles our Deathstalkers have had in their scouting efforts.\n\nYour aid to our Deathstalkers was invaluable, {name}.  And you will be commended." } })
apply(450, { "classic", "forever" }, { deDE = { progress = "Wie ich sehe, seid Ihr wieder zurück, {name}.", completion = "Apotheker Berards Tagebuch! Ihr seid wirklich recht tapfer, {name}. Jetzt lasst uns mal sehen, was Berard vorhatte, bevor er wahnsinnig wurde..." }, enUS = { progress = "I see you are back, {name}.", completion = "Apothecary Berard's journal!  Why you are quite brave, {name}.  Now let's see what Berard was up to before he went mad. . ." } })
apply(451, { "classic", "forever" }, { deDE = { progress = "Was führt Euch nach Undercity zurück, {name}?", completion = "Was für ein Schlag für die königliche Apothekervereinigung, Berard zu verlieren. Aber dank Eurer harten Arbeit und Apotheker Renferrels gewissenhaften Nachforschungen werden Berards Studien dennoch der dunklen Fürstin in ihrer Misere helfen können.\n\nWir stehen hier kurz vor einer großen Entdeckung, {name}. Wärt Ihr nicht so in der Kriegskunst erfahren, würde ich versuchen, Euch als Mitglied für die Vereinigung anzuwerben." }, enUS = { progress = "What brings you back to the Undercity, {name}?", completion = "Such a blow to the Royal Apothecary Society to lose Berard.  But through your hard work and Apothecary Renferrel's diligent research Berard's studies will still be useful to The Dark Lady's plight.\n\nWe are on the cusp of something great here, {name}.  If you were not so skilled in the ways of combat I would try to recruit you for membership in the Society." } })
apply(452, { "classic", "forever" }, { deDE = { completion = "Ihr habt wie ein wahrer Jünger der dunklen Fürstin gekämpft, {name}. Nachdem der Rat nun tot ist, können wir vielleicht ein für alle Mal die Kontrolle über diesen Ort erlangen und Arugal aus der Burg Shadowfang vertreiben. Ich ziehe den Hut vor Euch!" }, enUS = { completion = "You fought like a true disciple of the Dark Lady, {name}.  With the council dead, perhaps we can gain control of this town once and for all and drive Arugal from Shadowfang Keep.  I salute you!" } })
apply(453, { "classic", "forever" }, { deDE = { progress = "Wer seid Ihr?? Lasst mich in Ruhe!", completion = "<Jitters seufzt... >\n\nJa, ich bin der Autor dieses Buches. Ihr habt mich letztendlich dann doch gefunden, wie?\n\nNun, wenn Ihr dieses Tagebuch gelesen habt... dann wisst Ihr gerade mal die Hälfte!" }, enUS = { progress = "Who are you??  Leave me be!", completion = "<Jitters sighs...>\n\nYes, I'm the author of that book.  You finally found me, eh?\n\nWell if you read that journal...then you only know the half of it!" } })
apply(454, { "classic", "forever" }, { deDE = { completion = "Hallo, {class}.\n\nIhr werdet mich zur Ausgrabungsstätte begleiten? Das hört man gern... Wer weiß, was die Dunkeleisenzwerge nach Saean und seinen Spießgesellen noch alles auf Lager haben?\n\nWie auch immer, lasst mich nur noch einige letzte Kontrollen durchführen. Sprecht wieder mit mir, wenn Ihr abreisefertig seid." }, enUS = { completion = "Hello, {class}.\n\nYou'll be escorting me to the excavation site? That's good to hear... After Saean and his cronies, who knows what else the Dark Irons might have up their sleeves?\n\nAnyways, let me just make some final checks. Talk to me again when you're ready to go." } })
apply(455, { "classic", "forever" }, { deDE = { completion = "Euer Bericht enthält viele schlechte Nachrichten!\n\nIch weiß, dass die Dragonmaw verstärkt nach Algaz hineindrängen. Normalerweise verstecken sich die Dragonmaw nur oben in den Hügeln. Was sie dazu gebracht hat, nach Algaz hineinzuströmen, ist immer noch ein Rätsel... \n\nDanke, {name}. Und wir werden wahrscheinlich Eure Hilfe wünschen, wenn es darum geht, sich um diese Orcs zu kümmern." }, enUS = { completion = "Your report is full of bad news!\n\nI see the Dragonmaws are making a strong move into Algaz.  Normally the Dragonmaws just hide up in the hills.  What made them surge into Algaz is still a mystery...\n\nThank you, {name}.  And we'll probably want your help dealing with these orcs." } })
apply(456, { "classic", "forever" }, { deDE = { completion = "Ihr habt Eure Pflichten gut erfüllt, {name}." }, enUS = { completion = "You performed your duties well, {name}." } })
apply(457, { "classic", "forever" }, { deDE = { completion = "Ihr habt Eure Hingabe an die Natur deutlich bewiesen, {name}. Ein junger {class} wie Ihr hat eine viel versprechende Zukunft vor sich." }, enUS = { completion = "You have proven your dedication to nature well, {name}.  A young {class} like yourself has a promising future." } })
apply(458, { "classic", "forever" }, { deDE = { completion = "Es sieht so aus, als hättet Ihr mich gefunden, junger {race}. Melithar ist ein weiser Druide, wenn er Euch geschickt hat." }, enUS = { completion = "I see you found me, young {race}.  Melithar is a wise druid to have sent you." } })
apply(459, { "classic", "forever" }, { deDE = { progress = "Bestätigt meinen Verdacht, {name}. Bringt mir 8 Stücke Teufelsmoos.", completion = "Der Dienst, den Ihr den Lebewesen in Shadowglen erwiesen habt, ist eine Belohnung wert, {name}.\n\nLeider habt Ihr aber dennoch meine Befürchtungen bestätigt. Wenn die Grells von dem Teufelsmoos besudelt wurden, dann ist kaum auszudenken, was aus den Furbolgs des Knarzklauenstamms geworden ist, die einst hier lebten.\n\nSolltet Ihr Euch jemals in Dolonaar wiederfinden, {class}, sucht den klugen Druiden Athridas Bearmantle auf. Er teilt unsere Sorge um das Wohlergehen des Waldes." }, enUS = { progress = "Satisfy my suspicions, {name}.  Bring to me 8 Fel Moss.", completion = "Your service to the creatures of Shadowglen is worthy of reward, {name}.\n\nYou confirmed my fears, however.  If the grells have become tainted by the Fel Moss, one can only imagine what has become of the Gnarlpine tribe of furbolgs who once lived here.\n\nShould you find yourself in Dolanaar, able {class}, seek out the knowledgeable druid, Athridas Bearmantle.  He shares our concern for the well being of the forest." } })
apply(460, { "classic", "forever" }, { deDE = { progress = "Dieses Grab wurde in aller Eile gebuddelt.", completion = "Danke, {name}. Ich hatte schon befürchtet, die Gnolle hätten meinen Körper zerstört. Gut zu wissen, dass dem nicht so ist." }, enUS = { progress = "This grave was hastily dug.", completion = "Thank you, {name}.  I had feared the Gnolls destroyed my body.  It is good to know they did not." } })
apply(461, { "classic", "forever" }, { deDE = { progress = "Hier ist es! Bringt mich etwas näher heran...", completion = "Na bitte, sie ist offen. Lasst mich hier. Ich habe die besten Jahre meines Lebens in dieser Burg verbracht, und der Gedanke daran, in diesen Mauern zu ruhen, wirkt tröstlich.\n\nAchtet darauf, die Nische ordentlich zu schließen - ich möchte nicht von diesen Moderfellen gefunden werden.\n\nOh, und nehmt dies. Ihr habt es Euch verdient." }, enUS = { progress = "This is the spot!  Bring me closer...", completion = "There we are, it's open.  Leave me here.  I spent the best days of my life in this keep, and the thought of resting within its walls gives me comfort.\n\nBe sure to close the alcove tight - I don't want those Rot Hides to find me.\n\nOh, and take this.  You've earned it." } })
apply(464, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Lager der Dragonmaw angegriffen?", completion = "Gut gekämpft, {name}. Die Dragonmaw sind keine solche Bedrohung mehr wie zu den Zeiten, als sie noch Drachen unter sich hatten, aber sie sind dennoch harte Gegner.\n\nDie Dragonmaw werden angeführt von Nek'rosh, Sohn von Nekros, der vor vielen Jahren der Anführer der Dragonmaw war. Nekros verwendete mächtige Magie, um die roten Drachen zu bändigen, aber als ihn diese Magie im Stich ließ ... waren die Drachen nicht glücklich.\n\nNekros wurde getötet, und sein Sohn hat Rache an den Drachen geschworen, die seinen Vater erschlugen." }, enUS = { progress = "Have you attacked the Dragonmaw encampment?", completion = "Well fought, {name}.  The Dragonmaws are not the same threat they were when they had dragons, but they're still fierce opponents.\n\nThe Dragonmaws are led by Nek'rosh, son of Nekros, who was the former head of the Dragonmaws years ago.  Nekros used powerful magic to tame the Red Dragons, but when that magic failed him...the dragons were not happy.\n\nNekros was killed, and his son has vowed revenge against the dragons who slew his father." } })
apply(465, { "classic", "forever" }, { deDE = { progress = "Ihr seht das erste Katapult vor Euch. Wollt Ihr es entzünden?", completion = "Ihr legt etwas von dem Zunder auf das Katapult und schlagt dann einen Funken darauf.\n\nFlammen schlagen hervor und breiten sich schnell aus!" }, enUS = { progress = "The first catapult is before you.  Will you set it aflame?", completion = "You place some of the tinder on the catapult then strike a spark onto it.\n\nFlame erupts and quickly spreads!" } })
apply(466, { "classic", "forever" }, { deDE = { progress = "Wo ist denn das Erz, {name}?!", completion = "Ihr habt das Erz! Gut gemacht, {name}! Ich werde sofort jemanden damit arbeiten lassen. Wollen wir hoffen, dass er sich dabei nicht in die Luft sprengt!" }, enUS = { progress = "Where is that ore, {name}?!", completion = "You got the ore!  Well done, {name}!  I'll get someone to work with this right away.  Let's hope he doesn't blow himself up!" } })
apply(467, { "classic", "forever" }, { deDE = { completion = "Hallo {name}. Ihr seid hier wegen des Auftrags, den ich habe, hm? Es tut gut zu sehen, dass Ihr ein junger {race} seid, dessen Blut bei der Aussicht auf Abenteuer in Wallung gerät." }, enUS = { completion = "Hello {name}.  You're here about the task I have, eh?  It's good to see a young {race} like yourself whose blood burns at the prospect of adventure!" } })
apply(468, { "classic", "forever" }, { deDE = { completion = "Hallo, {class}! Ihr seid wegen der Spähmission hier, stimmt's? Sehr gut!\n\nIch hoffe, Eure Ausrüstung ist in gutem Zustand, denn aus dieser \"Späh\"-Mission ist ein... größerer Schlamassel geworden." }, enUS = { completion = "Hello, {class}!  You're here for the scouting mission, are you?  Very good!\n\nI hope your gear is in good condition, because this \"scouting\" mission has changed into something more messy..." } })
apply(469, { "classic", "forever" }, { deDE = { progress = "Guten Tag auch, {class}. Kann ich Euch für ein Paar Stiefel interessieren? Vielleicht einige frisch gegerbte Häute?", completion = "Hmm, das ist von Einar, oder? Er hat mir schon seit bald einer Woche seine Häute nicht mehr persönlich geliefert. Er hat sicher wieder Ärger mit seiner Frau!\n\nVielleicht lasse ich meine Frau mal mit Sida sprechen..." }, enUS = { progress = "Hello there, {class}. Could I interest you in a pair of boots?  Perhaps some newly cured skins?", completion = "Hmm, this is from Einar, right? Hasn't delivered his skins to me in person for almost a week now. No doubt it's some differences with the wife!\n\nMaybe I'll have my wife go speak with Sida sometime..." } })
apply(470, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meine Tasche gefunden?", completion = "Oh, danke sehr, {name}! Ich hatte schon befürchtet, sie wäre für immer verloren!\n\n\n\nHm, ich kann damit nicht mehr viel anfangen, aber wenn Ihr sie sauber macht, könnt Ihr sie bestimmt noch gebrauchen." }, enUS = { progress = "Did you find my bag?", completion = "Oh, thank you, {name}! I was afraid that it was lost for good!\n\n\n\nHm, I don't have much use for this anymore, but wash it off and I'm sure you could make use of it." } })
apply(471, { "classic", "forever" }, { deDE = { progress = "Mein Lehrling ist wie ein Sohn für mich. Wird hart für ihn sein, sein Leben mit nur einem Bein zu fristen.\n\nAh, {name}, wie läuft's? Habt Ihr meine Häute?", completion = "Hmm... Ihr habt nicht zufällig Lust, bei mir in die Lehre zu gehen?\n\nHa! Nein, war nur ein Witz. Ihr seid sowieso viel zu alt. Außerdem - nach Eurem Aussehen zu urteilen, habt Ihr wahrscheinlich andere Ambitionen im Leben. Dennoch habt Ihr da ein paar feine Häute besorgt und ich werde damit etwas anfangen können." }, enUS = { progress = "My apprentice is like a son to me.  It's going to be hard for him to live his life with only one leg.\n\nAh, {name}, how goes it?  Do you have my skins?", completion = "Hmm... Don't suppose you'd be interested in becoming my apprentice, would you?\n\nHah! No, I'm just kidding. You're much too old, for one thing.  Besides - from the looks of you, it would seem that you have other ambitions in life.  Nonetheless, these are some fine skins you've procured, and I'll be able to put them to good use." } })
apply(472, { "classic", "forever" }, { deDE = { completion = "Welcher mutige {class} bringt Kunde aus Menethil? Ah, {name} werdet Ihr genannt.\n\nIhr bringt Hoffnung in eine hoffnungslose Situation. Gut zu wissen, dass der junge Harlo überlebt hat. Auf der Flucht wurde ihm eine ernste Wunde zugefügt. Wir hatten kaum die Zeit, ihn auf dem Rücken des letzten überlebenden Reittiers unseres Regiments fortzuschicken.\n\nAber wir sind hier in einer gefährlichen Lage. Dun Modr ist gefallen, und wir sind nur ein Schatten des großen Regiments, das wir einmal waren." }, enUS = { completion = "What brave {class} sends word from Menethil?  Ah {name}, they call you.\n\nYou bring hope to a hopeless situation.  'Tis good news indeed that young Harlo survived.  While fleeing he received a grievous wound.  We had but little time to send him on his way on the back of the only surviving steed with the regiment.\n\nBut now we face a perilous situation.  Dun Modr has fallen and we are but a shadow of the great regiment we once were." } })
apply(473, { "classic", "forever" }, { deDE = { completion = "{name}. Valstag klärte mich über Eure bisherigen Erfolge mit den Orcs des Dragonmawklans in Dun Algaz auf. Ihr seid ein {race} von Wert.\n\nUnd ich habe eine Aufgabe für Euch." }, enUS = { completion = "{name}.  Valstag briefed me on your past success with the Dragonmaw Orcs at Dun Algaz.  You're a {race} of worth.\n\nAnd I have a task for you." } })
apply(474, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Nek'rosh getötet?", completion = "Saubere Arbeit, {name}. Ihr habt den Orcs vom Dragonmawklan einen deutlichen Schlag verpasst. Vielleicht erholen sie sich nie wieder davon. Außerdem hat die Zerstörung dieser Katapulte den Hafen von Menethil gesichert.\n\nIhr seid ein vorzüglicher {race}, und das Königreich von Ironforge belohnt die, die ihm gut dienen." }, enUS = { progress = "Have you killed Nek'rosh?", completion = "Stoutly done, {name}.  You have dealt a telling blow to the Dragonmaw orc clan.  They may never recover.  And the destruction of those catapults has made Menethil Harbor safe.\n\nYou are a {race} of merit, and the kingdom of Ironforge rewards those who serve it well." } })
apply(475, { "classic", "forever" }, { deDE = { completion = "Dank sei den Waldgeistern, dass Ihr hier seid! Ich wusste, Athridas würde die Probleme spüren und Hilfe schicken." }, enUS = { completion = "Thank the forest spirits you are here!  I knew Athridas would sense trouble and send help." } })
apply(476, { "classic", "forever" }, { deDE = { completion = "Bei den Sternen! Dies ist wirklich sehr furchterregend!" }, enUS = { completion = "By the stars!  This is quite disturbing indeed!" } })
apply(477, { "classic", "forever" }, { deDE = { completion = "<Als Ihr den Kistendeckel aufstemmt, findet Ihr eine Anzahl sorgfältig verpackter Objekte. Oben auf der Kiste liegt ein Bündel vergilbter Landkarten, auf denen anscheinend der Silberwald und andere Teile von West-Lordaeron abgebildet sind.\n\nUnter den Landkarten liegt ein geheimnisvoll aussehender magischer Anhänger.>" }, enUS = { completion = "<Prying open the lid of the crate, you find an assortment of carefully-packed objects. On the top of the crate lies a bundle of maps, yellowing with age, that appear to depict Silverpine Forest and other parts of western Lordaeron.\n\nUnderneath the maps is a mysterious-looking magical pendant.>" } })
apply(478, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas Nützliches erfahren, {name}?", completion = "Karten und diesen... Anhänger, hm? Interessant.\n\nEs ist offensichtlich, dass die Hexer von Dalaran sich aus einem bestimmten Grund für Ambermill interessieren, aber ihr Ziel ist mir bislang noch verborgen.\n\nVielleicht weiß Dalar etwas über ihren Zweck." }, enUS = { progress = "Have you learned anything useful, {name}?", completion = "Maps and this... pendant, hm? Interesting.\n\nIt is obvious that the Dalaran wizards are interested in Ambermill for some purpose, but still, their aim is hidden to me.\n\nPerhaps Dalar will know something of their use." } })
apply(479, { "classic", "forever" }, { deDE = { progress = "Wir müssen uns eilen, ihr Plan darf keinerlei Früchte tragen, oder wir können unsere Herrschaft über den Silberwald verlieren.", completion = "Dalar hat herausgefunden, dass trotz des Rückschlags das Wirken schon weit fortgeschritten ist.\n\nEin sehr mächtiger Hexer leitet die magische Energie. Er muss schnellstmöglich aufgehalten werden." }, enUS = { progress = "We must hurry, their plans must not come to fruition, or we may lose our hold on Silverpine Forest.", completion = "Dalar has found that the weaving is quite far along, despite the setback.\n\nA wizard of great power is guiding the magic energy. He must be stopped quickly." } })
apply(480, { "classic", "forever" }, { deDE = { progress = "Schnell, die Zeit ist knapp, {name}!", completion = "Die Magie der Hexer löst sich auf und die Leyenergien kehren in ihren Ruhezustand zurück. {name}, Eure Bemühungen waren erfolgreich. Wir haben unseren Feinden einen mächtigen Schlag versetzt, wie auch den übermächtigen Hexern von Dalaran.\n\nDennoch müssen wir weiterhin wachsam sein, da wir wissen, dass die Quelle der Energie so nahe liegt... Für die Zukunft müssen Pläne gemacht werden." }, enUS = { progress = "Quickly, time runs short, {name}!", completion = "The magic of the wizards dissipates, and the ley energies fade into dormancy. Your efforts have been fruitful, {name}, and we have dealt a major blow to our enemies, and to the overbearing wizards of Dalaran.\n\nWe must be vigilant, however, knowing that source of energy lies so close at hand... Plans must be made for the future." } })
apply(481, { "classic", "forever" }, { deDE = { progress = "Ja, {class}? Was ist?", completion = "Interessant, weitere Machenschaften der Kirin Tor, wie es scheint. Dies ist ein mächtiges Artefakt. Es wurde häufig von mächtigen Hexern der Kirin Tor benutzt, um magische Energien zu kanalisieren.\n\nDie Anzahl, die sie davon nach Ambermill bringen, sagt mir, dass sie ein Projekt großen Ausmaßes durchführen wollen.\n\nIch werde versuchen, ihre Schilde zu durchdringen und ihre Absicht zu ermitteln." }, enUS = { progress = "Yes, {class}? What is it?", completion = "Interesting, more machinations of the Kirin Tor, it would seem. This is a powerful artifact. It was used frequently by powerful wizards of the Kirin Tor to channel magical energies.\n\nThat they are delivering so many to Ambermill indicates that they must be undergoing a project of some magnitude.\n\nI will see if I can pierce their shields and ascertain their intent." } })
apply(482, { "classic", "forever" }, { deDE = { completion = "Ihr bringt schlechte Neuigkeiten, {name}. Sollte Dalar recht behalten - und ich habe keinerlei Grund, dies zu bezweifeln - müssen wir schnell handeln.\n\nIch muss unseren Angriffsplan mit ihm beraten. In der Zwischenzeit müssen wir ihr Weiterkommen aufhalten." }, enUS = { completion = "Ill news you bring, {name}. If Dalar is correct--and I've no reason to believe he isn't--we must move quickly.\n\nI must confer with him on our plan of attack. But in the meanwhile we will have to delay their progress." } })
apply(483, { "classic", "forever" }, { deDE = { progress = "{name}, die entführten Druiden der Kralle werden auf ewig im Smaragdgrünen Traum gefangen gehalten, wenn wir die Relikte des Erwachens nicht aus dem Grabhügel von Ban'ethil im Westen herbringen können.\n\nJede Minute, die wir zögern, bringt ihr Schicksal einen Schritt näher an die ewige Verdammnis.", completion = "Ihr hattet Erfolg, junger {class}! Gut gemacht. Und gerade rechtzeitig, wie ich hinzufügen möchte." }, enUS = { progress = "{name}, the kidnapped Druids of the Talon will be forever trapped in the Emerald Dream if we cannot retrieve the Relics of Wakening from the Ban'ethil Barrow Den to the west.\n\nFor every minute we delay their fate comes one step closer to eternal doom.", completion = "You have succeeded, young {class}!  Well done.  And just in time I might add." } })
apply(484, { "classic", "forever" }, { deDE = { progress = "{name}, nicht wahr? Habt Ihr meine Häute?", completion = "Ihr habt gute Arbeit geleistet, {name}. Die Qualität dieser Häute ist superb. Ich muss so bald wie möglich mit dem Gerben dieser Häute beginnen. Oh, bevor ich jedoch damit anfangen kann, habe ich noch eine andere Aufgabe zu erledigen. Ich denke, dass Ihr sie übernehmen könnt." }, enUS = { progress = "{name}, right? Do you have my skins?", completion = "Nice work you've done here, {name}. The quality of these skins is superb. I'll have to get them into the curing process as soon as possible. Oh, but before I get to that, there's some other work I need done that I think you might be able to take care of." } })
apply(485, { "classic", "forever" }, { deDE = { progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-09/HL funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"" }, enUS = { progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-09/HL is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"" } })
apply(486, { "classic", "forever" }, { deDE = { completion = "{name}, Ihr habt Euch als ein zutiefst würdiger und geschickter {class} erwiesen. Ein {race}, welcher dem Pfad der Ehre so sicher folgt wie Ihr, findet mit Sicherheit großen Ruhm in dieser Welt.\n\nMögen die Waldgeister Euch auf all Euren Wegen beschützen." }, enUS = { completion = "{name} you have proven yourself a most worthy and able {class}.  A {race} who follows the path of honor as sure as you do is certain to find great glory in this world.\n\nMay the forest spirits protect you wherever your travels may take you." } })
apply(487, { "classic", "forever" }, { deDE = { progress = "Die Straße ist noch immer nicht sicher, {class}. Kehrt um und erschlagt 6 Wegelagerer der Knarzklauen und kommt zu mir zurück.", completion = "Ihr habt den guten Leuten von Dolanaar und Darnassus gute Dienste geleistet, tapferer {class}. Als Mitglied der Schildwache von Teldrassil beglückwünsche ich Euch zu Euren Bemühungen." }, enUS = { progress = "The road is still not safe, {class}. Travel forth and slay 6 Gnarlpine Ambushers and return to me.", completion = "You have served the good people of Dolanaar and Darnassus well, brave {class}.  As a member of the Sentinel force of Teldrassil I salute your efforts." } })
apply(488, { "classic", "forever" }, { deDE = { progress = "Ihr wart also ein fleißiges Bienchen, {name}? Ich habe darauf gewartet, dass Ihr mir das bringt, was ich benötige.", completion = "Ha ha! Wirklich hervorragend.\n\nWer hätte jemals gedacht, dass ein {race} mir, Zenn Foulhoof, meine Wünsche erfüllen würde? Selbst ich hätte es nicht geglaubt. Aber so geht es nun mal... unsere so geliebte Welt ist doch voller Überraschungen.\n\nEin Hoch auf die Naiven und Gutgläubigen!" }, enUS = { progress = "Have you been a busy little bee, {name}?  I've been waiting for you to bring me what I need.", completion = "Ha ha!  Well, done indeed.\n\nWho would have ever guessed that I, Zenn Foulhoof, would have a {race} to do my bidding?  Certainly not me!  But so it goes... this beloved world of ours is full of surprises.\n\nThree cheers for the naive and gullible!" } })
apply(489, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr für mich, {name}? Eine leckere kleine Zwischenmahlzeit, nehme ich an?", completion = "Wie nett von einem {race}! Ich wusste, dass Ihr nützlich sein würdet!" }, enUS = { progress = "What do you have for me, {name}?  A lovely snack I presume?", completion = "Ah, what a sweet {race}!  I knew you would come in handy!" } })
apply(491, { "classic", "forever" }, { deDE = { progress = "{name}. Habt Ihr Thule Rabenklaue besiegt?", completion = "... was ist das? Thule hatte unseren gewebten Zauberstab? Ich dachte, er sei verloren, als unsere Freundschaft zerbrach und er sich auf die Seite des Lichkönigs stellte!\n\nEr kann seine Macht nie verwendet haben, denn das hätte ich gespürt. Und es ist gut, dass er ihn nicht benutzt hat...\n\nDies ist ein wunderbarer Fund. {name}, Ihr habt meinen Dank und sollt belohnt werden." }, enUS = { progress = "{name}.  Have you defeated Thule Ravenclaw?", completion = "...what is this?  Thule had our Woven Wand?  I thought it was lost when our friendship sundered and he sided with the Lich King!\n\nHe must not have invoked its power, for if he had I would have sensed it.  And it is good that he did not use it...\n\nThis is a marvelous find.  You have my gratitude, {name}, and will be rewarded." } })
apply(492, { "classic", "forever" }, { deDE = { progress = "Hätte ich nur mein getreues Gewehr bei mir, wärt Ihr so gut wie tot, {class}. Wartet nur, bis die Dampfpanzerbrigade eintrifft, um mich zu retten!", completion = "Ah, endlich, etwas zu trinken. Das ist zwar sicherlich kein Rhapsody-Malz, aber zum jetzigen Zeitpunkt ist mir alles recht, um meine Kehle anzufeuchten." }, enUS = { progress = "Why if I had my trusted rifle you'd be as good as dead, {class}.  Just wait until the Steam Tank Brigade arrives to rescue me!", completion = "Ah, a drink at last.  I'm sure it's no Rhapsody Malt but I'll take anything to whet the old whistle at this point." } })
apply(493, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas für mich?", completion = "Ah, wie wunderbar. Ich habe den größten Respekt vor Apotheker Renferrel. Ich brenne darauf, seine Arbeiten zu studieren." }, enUS = { progress = "You have something for me?", completion = "Ah, most excellent.  Apothecary Renferrel has my utmost respect.  I am anxious to study his work." } })
apply(494, { "classic", "forever" }, { deDE = { completion = "Der Schrei des Raben locket vom Westen her?\n\nWas für superbe Neuigkeiten! Hillsbrad ist reif für den Angriff. Jetzt können wir unseren Zerstörungsplan durchführen. Das wird Varimathras erfreuen." }, enUS = { completion = "The raven's cry from the west doth beckon?\n\nSuperb news!  Hillsbrad is ripe for attack.  We can carry out our plan of destruction now.  Varimathras will be pleased." } })
apply(495, { "classic", "forever" }, { deDE = { completion = "Ihr wurdet von Shalindra geschickt? Nun gut, Ihr werdet sehen, dass ich nicht viel Zeit mit Geplauder verplempere.\n\nMug'Thol ist ein Ärgernis und wir werden uns um ihn kümmern, schnell, gründlich und ohne Zwischenfälle." }, enUS = { completion = "You were sent by Shalindra? Very well then, you'll find I don't waste much time with idle chatter.\n\nMug'Thol is an irritant, and we will deal with him quickly, thoroughly, and without incident." } })
apply(496, { "classic", "forever" }, { deDE = { progress = "Wie ich sehe, seid Ihr zurück. Ich hoffe, Ihr konntet mir die Zutaten beschaffen, die ich benötige. Diese Todesfreien Tage machen mich immer so trübsinnig.", completion = "Diese Exemplare sind perfekt. Nun, {name}, Ihr habt es vollbracht, mir eine winzigkleine Freude an einem weiteren dieser elendiglichen Tage zu machen. Ich weiß Eure Bemühungen zu schätzen." }, enUS = { progress = "I see you are back.  I hope you were able to gather the agents I need.  Another deathless day will put me in such a gloomy mood.", completion = "These specimens are perfect.  Well, {name}, you have managed to bring me the slightest hint of joy on yet another miserable day.  Your efforts are appreciated." } })
apply(498, { "classic", "forever" }, { deDE = { completion = "Die Menschen wollten also unsere Krieger zu Sklaven machen, wie? Wir werden es ihnen zeigen!\n\nEs scheint, als hätten sie Gol'dir, unseren Anführer, an einen anderen Ort gebracht. Wir müssen ihn finden und befreien. Aber wir haben im Moment keine Ahnung, wo er sich befindet ...\n\nSobald wir eine Spur haben, werde ich Euch mit Sicherheit benachrichtigen, {name}." }, enUS = { completion = "So the humans thought to turn our warriors into slaves, did they? We'll show them!\n\nIt would seem that they have taken Gol'dir, our leader, to another location. We must find him and rescue him. But we currently have no clue where he is...\n\nWhen we have a lead, I will be sure to tell you, {name}." } })
apply(499, { "classic", "forever" }, { deDE = { progress = "Quaaaaak!", completion = "Quak!" }, enUS = { progress = "Ribbit!", completion = "Croak!" } })
apply(500, { "classic", "forever" }, { deDE = { progress = "{name}, immer noch auf Ogerjagd? Habt Ihr die Knöchelknochen, die Ihr laut meinem Befehl sammeln solltet?", completion = "Sehr gut, {name}. Ihr müsst Euch durch eine ganze Schiffsladung Oger gehackt haben, um diese Anzahl Knöchelknochen zu erhalten.\n\nDas sollte sie uns vom Halse halten. Zumindest für eine kleine Weile." }, enUS = { progress = "{name}, are you still hunting ogres?  Do you have the knucklebones I had you gather?", completion = "Very good, {name}.  You must have hacked through a whole mess of ogres to get all these knucklebones.\n\nThat should keep them out of our hair.  At least, for a while." } })
apply(501, { "classic", "forever" }, { deDE = { progress = "Ich erinnere mich an Euch, {name}. Ihr wolltet mir dabei helfen mein neuestes Elixier zu brauen. Das Blut brauche ich, um den Einwohnern von Hillsbrad mein höchsteigenes, hausgemachtes Spezial-Elend zu präsentieren.", completion = "Wunderbare Sammlung, {name}." }, enUS = { progress = "I remember you, {name}.  You were going to help me out in concocting my latest elixir.  I'll need that blood before I can bring my own special brand of misery to the inhabitants of Hillsbrad.", completion = "Superb collecting, {name}." } })
apply(502, { "classic", "forever" }, { deDE = { progress = "Wuff?", completion = "Ihr schüttet etwas von dem Elixier in Eure Hand und haltet es vor Stanleys Schnauze." }, enUS = { progress = "Woof?", completion = "You pour some of the elixir into your hand and hold it before Stanley's mouth." } })
apply(503, { "classic", "forever" }, { deDE = { progress = "Gebt mir den Schlüssel, {class}, ich werde das Schloss selbst aufschließen.", completion = "Danke, {name}. Laut Befehl des Kriegshäuptlings hatte ich die Führung der Expedition von Durotar, aber wie Ihr sehen könnt, lief es nicht ganz so wie eigentlich geplant. Sie haben mich in dieser Stadt gefangen gehalten, mich gezwungen zu arbeiten, ich musste Lasten tragen, graben...\n\nWas ich erlitten habe, ist jedoch unwichtig. Ich habe wichtige Informationen, die Ihr dem jetzigen Anführer unserer Gruppe überbringen müsst." }, enUS = { progress = "Give me the key, {class}, I will undo the lock myself.", completion = "Thank you, {name}. I led the expedition from Durotar under the Warchief's orders, but as you can see, our plans went somewhat awry. They have held me captive here in this town, forcing me to work, hauling burdens, digging...\n\nWhat I have suffered is unimportant, however. There is important information you must deliver to whomever is leading our group now." } })
apply(504, { "classic", "forever" }, { deDE = { completion = "Sehr gut. Hier ist Eure Belohnung.\n\nAls Ihr diese Kriegstreiber gesehen habt, konntet Ihr sehen, wie es um die Stadt von Alterac bestellt ist? Ich nehme an, nicht sehr gut. Oger sind nicht gerade für ihre Reinlichkeit bekannt.\n\nDank Eurer Bemühungen werden sie sich wohl jetzt von Southshore fern halten." }, enUS = { completion = "Very good.  Here is your reward.\n\nAnd when you were hunting those Warmongers, how did Alterac city look?  It's in bad shape I would guess.  Ogres are not known for their cleanliness.\n\nThankfully, your efforts will help keep them away from Southshore." } })
apply(505, { "classic", "forever" }, { deDE = { completion = "Danke, {name}. Ein Teil dieser Bande dürfte zwar noch immer hier herumlungern, aber wir hoffen, dass einige der Diebe und Schleicher, die Ihr erschlagen habt, für den Tod des letzten Magistraten verantwortlich waren. Doch selbst wenn dem nicht so wäre, stellt das Syndikat auf jeden Fall eine Besudelung dieses Landes dar und ist ein Schandfleck für das gesamte Volk der Menschen. \n\nSouthshore wird ihren Tod begrüßen." }, enUS = { completion = "Thank you, {name}.  Although they may still be lurking about, we hope that some of the thieves and footpads you slew were responsible for the last magistrate's death.  But even if they weren't, the Syndicate is a taint on this land and a stain on the human race.  \n\nTheir deaths are welcome to Southshore." } })
apply(506, { "classic", "forever" }, { deDE = { completion = "Diese überheblichen Menschen haben vielleicht Nerven! Wir werden ihnen zeigen, dass die Orcs sich ihrem Willen niemals unterwerfen werden!\n\nDas wird nun unsere Mission, zusätzlich zur Bergung des Schmuckstücks, das der Kriegshäuptling zu haben wünscht. Es scheint, als würde das Erfüllen der einen Mission gleichzeitig die Erfüllung der anderen bedeuten." }, enUS = { completion = "The nerve of those overbearing humans! We'll show them that the orcs shall never submit to their will!\n\nThis will now be our mission, in addition to recovering the trinket the Warchief desires. It would seem that by accomplishing one, we will also accomplish the other." } })
apply(507, { "classic", "forever" }, { deDE = { progress = "W-was wollt Ihr?", completion = "Nein, nein, bitte tut mir nichts! Ich wollte Eurem Volk niemals Schaden zufügen, er hat mich gegen meinen Willen genommen! Ich flehe Euch an... verschont mich!" }, enUS = { progress = "W-what do you want?", completion = "No, no please don't hurt me! I never meant your people any harm, he's had me against my will! Please... spare me!" } })
apply(508, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurückgekehrt, {name}. Habt Ihr einen Erfolg zu vermelden?", completion = "Es ist schon merkwürdig, dass der Kriegshäuptling so viel Aufwand um so ein kleines Ding macht. Ich behaupte nicht, dass ich ihn verstehe, aber ich folge ihm, egal wie seine Befehle lauten. Ihr habt gute Arbeit geleistet, {name}, der Kriegshäuptling wird über Euren Erfolg erfreut sein." }, enUS = { progress = "You've returned, {name}. Success to report?", completion = "It is strange that the Warchief would expend so much over such a small thing. I do not claim to understand him, but I will follow him, whatever his commands. You did well, {name}, no doubt the Warchief will be glad to hear of your success." } })
apply(509, { "classic", "forever" }, { deDE = { progress = "Hattet Ihr Erfolg in der Nethander-Siedlung?", completion = "Ah, der fürchterliche Gestank von Morastschnauzenkappen. Wenigstens sind diese dreckigen Gnolls für etwas gut." }, enUS = { progress = "Any luck at Nethander Stead?", completion = "Ah, the horrible reek of Mudsnout Blossoms.  At least those filthy Gnolls are good for something." } })
apply(510, { "classic", "forever" }, { deDE = { progress = "{name}, Ihr seht so besorgt aus. Möchtet Ihr mir etwas mitteilen?", completion = "<Maleb liest die Dokumente.>\n\nDas ist wirklich sehr beunruhigend, {name}. Aus den Informationen in diesen Dokumenten und aus früheren Aktionen des Syndikats geht hervor, dass diese Bande von Halsabschneidern Southshore den Krieg erklärt hat." }, enUS = { progress = "{name}, you look anxious.  Is there something you wish to tell me?", completion = "<Maleb reads the documents.>\n\nThese are very troubling, {name}.  From the information in these documents, and from the Syndicate's actions in the past, we must assume that band of cutthroats has waged war on Southshore." } })
apply(511, { "classic", "forever" }, { deDE = { progress = "Ja, werter Herr? Was gibt es denn?", completion = "Was ist dies? Wartet einen Moment... lasst es mich genauer betrachten.\n\n...\n\nHm, ich habe diese Form der Verschlüsselung niemals gesehen, aber ich muss zugeben, dass mein Wissen auf diesem Gebiet bei weitem nicht vollständig ist." }, enUS = { progress = "Yes, sir?  Do you have some business with me?", completion = "What is this?  Hold a moment...let me take a closer look.\n\n...\n\nHm, I have never before seen this form of encryption, but I must admit that my knowledge in that area is by no means complete." } })
apply(512, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Syndikat gejagt? Habt Ihr die Ringe?", completion = "Wird das Syndikat seiner Adligen beraubt, geht auch seine Fähigkeit verloren, entschlossen zu handeln, und übrig bleibt nur eine Bande von Abschaum.\n\nIhr habt Eurer Allianz gut gedient, {name}." }, enUS = { progress = "Have you been hunting the Syndicate?  Do you have those rings?", completion = "Stripping the Syndicate of its nobility will remove its ability to act decisively, and reduce it to nothing more than a gang of thugs.\n\nYou serve your Alliance well, {name}." } })
apply(513, { "classic", "forever" }, { deDE = { progress = "Könnt Ihr nicht sehen, {class}, dass ich beschäftigt bin? Die dunkle Fürstin besteht auf einer neuen Pest, bevor die Vorhut der Geißel aus Northrend uns überwältigt. Und dann noch die menschliche Bedrohung aus dem Süden. Meine Zeit ist im Augenblick sehr wertvoll. Es ist hoffentlich von Bedeutung!", completion = "Apotheker Lydon hat Euch geschickt? Warum habt Ihr das nicht gleich gesagt!\n\nTrotz seiner etwas düsteren Einstellung ist Apotheker Lydon doch eines unserer hingebungsvollsten und geschicktesten Mitglieder.\n\nDer Gute schickt mir Morastschnauzengemisch! Nun weiß ich, was unser Freund in Hillsbrad vorhat. Und mir gefällt seine Denkweise. Die dunkle Fürstin wäre äußerst beeindruckt von dem Fortschritt, den er in Richtung neue Seuche macht." }, enUS = { progress = "Can you not see I am busy, {class}?  The Dark Lady insists on a new plague before the Scourge advance from Northrend overwhelms us.  And with the human threat pressing from the south, time becomes my most precious commodity.  This better be important!", completion = "Apothecary Lydon sent you?  Ah, why didn't you say so!\n\nDespite his gloomy disposition, Apothecary Lydon is one of our most dedicated and skilled members.\n\nThe good chap sends Mudsnout Composite!  I know what our friend in Hillsbrad is up to now.  And I like the way he thinks.  The Dark Lady would be most impressed with the progress he is making toward the new plague." } })
apply(514, { "classic", "forever" }, { deDE = { progress = "Dibbs aus Southshore hat Euch also geschickt? Wie geht’s dem alten Bücherwurm?", completion = "Ah, eine Verschlüsselung! Eine meiner Spezialitäten. Lasst mich mal sehen..." }, enUS = { progress = "Dibbs from Southshore sent you, did he?  How is the old bookworm doing?", completion = "Ah, encryption!  A specialty of mine.  Let me see here..." } })
apply(515, { "classic", "forever" }, { deDE = { progress = "Ich bin ja so froh, dass Ihr wieder da seid, {name}. Ich habe mich hier entsetzlich gelangweilt. Hier gab es ja nichts Unterhaltsameres zu tun, als Umpi zu vergiften und krank zu machen und sie dann wiederzubeleben... und das immer und immer und immer wieder.\n\nWie war Eure Reise nach Undercity? Hattet Ihr ein bisschen Glück und konntet ein paar Menschen auf dem Weg dorthin umbringen?", completion = "Die Aufregung dieses Experiments macht mich ganz schwummerig! Ihr wart so eine große Hilfe, {name}. Zusammen werden wir Krankheit und Tod in diesem Land verbreiten!" }, enUS = { progress = "So glad to see you back, {name}.  I was growing so terribly bored here.  Not a single entertaining thing to do besides poison and disease Umpi and reanimate her. . .over and over and over again.\n\nHow went the trip to the Undercity?  Were you fortunate enough to slaughter any humans along the way?", completion = "The excitement of this experiment has me feeling giddy!  You have been such a great help, {name}.  Together we will spread death and disease to this land!" } })
apply(516, { "classic", "forever" }, { deDE = { completion = "Wenn unsere Späher und Agenten weiterhin solch wertvolle Informationen beibringen, dauert es nicht mehr lange, bis wir die Geißel des Lichkönigs aus unserem Land vertrieben haben." }, enUS = { completion = "If our scouts and agents continue to procure valuable information such as this, we shall have the Lich King's Scourge removed from our lands in no time." } })
apply(517, { "classic", "forever" }, { deDE = { progress = "Manchmal wird mir hier in Tarrens Mühle so elendiglich langweilig, dass ich am liebsten einen Krug Formaldehyd öffnen möchte und sein liebliches Aroma durch die Luft ziehen ließe. Umpi wird dann aber immer so nervös.\n\nKonntet Ihr ein Fässchen von den Zwergen besorgen? Wenn ich auch nur noch einen Tag länger dieses Elixier anstarren muss, ohne es benutzen zu können, dann schreie ich.", completion = "Endlich! Dann können wir ja anfangen!" }, enUS = { progress = "Sometimes I get so bored out here in Tarren Mill I like to open up the formaldehyde jar and let the lovely aroma waft through the air.  Makes Umpi a little nervous though.\n\nSo were you able to get a keg from the Dwarves?  I swear if I have to stare at this deadly elixir without using it on someone for another day I am going to scream.", completion = "Finally!  Now we are ready for action!" } })
apply(518, { "classic", "forever" }, { deDE = { completion = "Der Schnee leuchtet rot von Ogerblut, aber wir dürfen unsere Bemühungen nicht einstellen, ehe nicht der Geist und die Zahl der Crushridge zermalmt und in den Dreck und Schnee getreten worden ist." }, enUS = { completion = "The snow blooms red with the blood of the ogres, but we cannot cease our efforts until the spirit and numbers of the Crushridge have been crushed and ground into the dirt and snow." } })
apply(519, { "classic", "forever" }, { deDE = { progress = "Ich will ihre Köpfe, {name}, keine Entschuldigungen.", completion = "... und ich dachte Oger röchen so schon ekelhaft genug.\n\nWenn Ihr mir Mug'Thols Kopf bringt, werde ich alle vier auf Stangen oberhalb Alteracs aufstellen lassen. Ein passendes Denkmal für alle diejenigen, die sich den Wünschen der dunklen Fürstin entgegenstellen." }, enUS = { progress = "I want their heads, {name}, not excuses.", completion = "...and I thought ogres smelled foul enough to begin with.\n\nWhen you bring me Mug'Thol's head, I will have the four of them mounted on pikes above Alterac. A fitting monument to those who go against the Dark Lady's wishes." } })
apply(520, { "classic", "forever" }, { deDE = { progress = "Drei Köpfe habe ich, einen vierten brauch ich noch. Das wird Mug'Thols sein, oder es wird der Eure, {name}. Das ist ein Versprechen.", completion = "Ihr habt Eure Pflicht gut erledigt, {name}. Mug'Thols Kopf wird die höchste Spitze der Ruinen von Alterac verzieren und die Todeswache wird die Überbleibsel der Crushridge in den Boden stampfen." }, enUS = { progress = "Three heads I have, a fourth I need. It will be Mug'Thol's, or it will be yours, {name}. That I promise.", completion = "You have done your duty well, {name}. Mug'Thol's head shall adorn the highest peak of the ruins of Alterac, and the Deathguard will sweep the remnants of the Crushridge into the ground." } })
apply(521, { "classic", "forever" }, { deDE = { progress = "Ja? Habt Ihr etwas zu berichten?", completion = "Das ist also das Relikt, das der Oger benutzte, um den Willen der dunklen Fürstin zu unterlaufen...\n\nSeltsam, dass etwas so Einfaches so eine große Macht ausüben kann. Und dazu noch in solch ungeschickte Hände fiel. Gut gemacht, {name}, ich werde die Krone Lady Sylvanas überbringen und dafür sorgen, dass sie von Eurem Verdienst hört." }, enUS = { progress = "Yes? Do you have something to report?", completion = "So this is the relic the ogre used to duck the will of the Dark Lady...\n\nStrange that something so simple could wield so great a power. And to fall into as clumsy hands as those. Well done, {name}, I will deliver the crown to Lady Sylvanas, and see that she hears of your accomplishment." } })
apply(522, { "classic", "forever" }, { deDE = { progress = "Ihr seid ja vollkommen außer Atem! Habt Ihr etwas zu berichten?", completion = "<Maleb inspiziert den Vertrag.>\n\nDas erklärt den letzten Angriff auf Southshore. Das Syndikat ist bestimmt auch hinter mir her, so wie hinter dem letzten Magistraten!" }, enUS = { progress = "You look out of breath!  Do you have something to report?", completion = "<Maleb inspects the contract.>\n\nThat explains the latest attack on Southshore.  The Syndicate must be after me, just as they were the last magistrate!" } })
apply(523, { "classic", "forever" }, { deDE = { progress = "Baron Vardus kann doch nicht im Ernst glauben, dass er ungestraft seine Rohlinge gegen Southshore aussenden kann. Ich will seinen Kopf!", completion = "Ich danke Euch, {name}. Jetzt kann ich ein wenig ruhiger schlafen, da ich weiß, dass dieser Schurke auf ewig schlafen wird." }, enUS = { progress = "Baron Vardus cannot think Southshore will allow him to send his thugs against us with impunity.  I want his head!", completion = "Thank you, {name}.  My head rests a little easier, knowing that villain lost his." } })
apply(524, { "classic", "forever" }, { deDE = { progress = "Ein muffiger Geruch steigt von dem Teppich empor.", completion = "Ihr stellt das besudelte Fässchen auf dem verstaubten Teppich ab." }, enUS = { progress = "A musty smell emanates from the rug.", completion = "You rest the tainted keg on the dusty rug." } })
apply(525, { "classic", "forever" }, { deDE = { progress = "{name}. Seid Ihr erneut durch die Vorgebirge und Berge gereist? Was für Neuigkeiten bringt Ihr mir?", completion = "<Maleb liest den Brief.>\n\nDas ist ein übersetzter Brief, den Ihr in einem Lager des Syndikats gefunden habt? Dieser Brief wurde nicht von einem Dieb geschrieben, und auch nicht von einem Edlen aus Alterac.\n\nEs scheint, als hätte das Syndikat Verbindung zu einer anderen Macht und allein bei dem Gedanken, welche es sein könnte, fährt es mir kalt den Rücken hinab." }, enUS = { progress = "{name}.  Have you been traveling through the foothills and mountains again?  What news do you bring?", completion = "<Maleb reads the letter.>\n\nThis is translated from a letter you found in a Syndicate encampment?  This was not written by a thief, or even a noble of Alterac.\n\nIt appears The Syndicate has ties to another power, and I shudder to think what that might be." } })
apply(527, { "classic", "forever" }, { deDE = { completion = "Rührt Euch, {class}. Ihr seid vom Kampf zurückgekehrt, wie ich sehe. Meine Quellen besagen, dass Ihr Euch an der Front in Hillsbrad tapfer geschlagen habt." }, enUS = { completion = "At ease, {class}.  I see you have returned from battle.  My sources tell me you performed well on the Hillsbrad front." } })
apply(528, { "classic", "forever" }, { deDE = { completion = "Die Schlinge um Hillsbrad zieht sich zu. Der Kampf läuft gut." }, enUS = { completion = "The grip of death is tightening around the town of Hillsbrad.  The battle goes well." } })
apply(529, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr Eure Befehle ausführen, {class}? Konntet Ihr Verringtan und seine Assistenten loswerden? Und wo ist diese Eisenlieferung?", completion = "Mission erfüllt, {class}. Und auf sehr geschickte Weise, wie ich hinzufügen möchte." }, enUS = { progress = "Were you able to carry out your orders, {class}?  Did you dispose of Verringtan and his assistants?  And where is that iron shipment?", completion = "Mission accomplished, {class}.  And carried out quite skillfully, I might add." } })
apply(530, { "classic", "forever" }, { deDE = { progress = "Habt Ihr diese Hände, {name}?", completion = "Ah, sehr gut. Diese Hände haben meine Frau, Deliah, getötet. Mein einziger Gedanke war Rache für ihren Tod, und Ihr wart das Instrument für diese Rache.\n\nHier, nehmt den Ring, den Ihr früher zurückbrachtet. Deliah ist für mich schon so lange tot, ihr Ring ist ein Schmuckstück, das ich nicht länger haben möchte. An seiner Statt werde ich diese Hände als Erinnerung an den Verrat meines Freundes behalten." }, enUS = { progress = "Do you have those hands, {name}?", completion = "Ah, good.  These hands killed my wife, Deliah.  Revenge for her murder was my only care, and you were the instrument of that revenge.\n\nHere, take the ring you returned earlier.  Deliah has been dead to me for so long, her ring is a bauble I no longer care to keep.  Instead, I will keep these hands as a remembrance of my friend's betrayal." } })
apply(531, { "classic", "forever" }, { deDE = { progress = "Sehr gute Arbeit, {name}! Wir habens ihm wirklich gezeigt! Hier, gebt mir den Kopf, ich werde mich darum kümmern.", completion = "Danke für Eure Hilfe bei meinem kleinen Plan, {name}. Seit Monaten wollte ich es diesem hochnäsigen, eingebildeten Jungen schon heimzahlen und ich würde meinen, es hat so richtig gut geklappt! Hier, nehmt das, Ihr habt es Euch verdient." }, enUS = { progress = "Great job, {name}! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, {name}. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it." } })
apply(532, { "classic", "forever" }, { deDE = { progress = "Welche Neuigkeiten habt Ihr?", completion = "Neuigkeiten über Eure Ruhmestaten in Hillsbrad reisen schnell. Ihr habt Eure Sache gut gemacht, {class}." }, enUS = { progress = "What news have you?", completion = "News of your glories in Hillsbrad traveled fast.  You have done well, {class}." } })
apply(533, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas erfahren können? Ich fürchte, dass Gol'dirs Aussichten von Tag zu Tag schlechter werden...", completion = "Endlich wissen wir, wo Gol'dir festgehalten wird. Das betreffende Lager befindet sich nicht allzu weit entfernt von hier. Es bleibt zu hoffen, dass sie nicht so gut vorbereitet sind wie damals, als sie uns das erste Mal gefangen nahmen." }, enUS = { progress = "Have you found anything? I fear Gol'dir's prospects grow worse by the day...", completion = "Finally, we know where Gol'dir is being held. The camp in question is not too far from here, and hopefully they will not be as well prepared as they were when they captured us the first time." } })
apply(535, { "classic", "forever" }, { deDE = { progress = "Habt Ihr mir etwas zu trinken gebracht, oder seid Ihr nur hier, um Eure Arbeit zu Ende zu führen?", completion = "In Anbetracht meines baldigen Todes möchte ich nur sagen, dass das hier das Süßeste ist, was ich jemals geschmeckt habe... Hier, nehmt das, wenn ich erst tot bin, nützt es mir sowieso nichts mehr.\n\nAlso, macht schon!" }, enUS = { progress = "Did you bring me something to drink or did you just come back to finish the job?", completion = "Given my impending death, I think I can safely say that this is the sweetest tasting thing ever... Here, take this, won't do me any good when I'm dead.\n\nWell, get on with it!" } })
apply(536, { "classic", "forever" }, { deDE = { completion = "Ich hoffe, das reicht aus, um Redpath davon zu überzeugen, dass ich - ha! - seine Befehle ausgeführt und Southshore von der schrecklichen und furchterregenden Bedrohung der Murlocs befreit habe. Denn es gibt ja auch nichts Schlimmeres als die Bedrohung seitens übergroßer Fische!" }, enUS = { completion = "I hope this will be enough to convince Redpath that I've--ha!--been carrying out his orders and ridding Southshore of the terrible and horrible menace of the dreaded murlocs! For there could be no greater evil than the ravages of overgrown fish!" } })
apply(537, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr die Abgesandten der Arguswacht finden?", completion = "Gut gemacht, {name}. Die Arguswacht sollte unserer Meinung nach nicht unbedingt die Gruppe sein, die das Syndikat leiten sollte.\n\nUnd auch wenn Ihr ihren Anführer hier getötet habt, diente Nagaz doch auch nur jemand anderem. Die Arguswacht ist möglicherweise im ganzen Kontinent von Azeroth verbreitet.\n\nOder sogar in der ganzen Welt." }, enUS = { progress = "Did you find the envoys of The Argus Wake?", completion = "Well done, {name}.  The Argus Wake does not sound like a group we want running the Syndicate.\n\nAnd although you may have destroyed their leader here, Nagaz was merely the servant of another.  The Argus Wake might run deep through the continent of Azeroth.\n\nOr even the world." } })
apply(538, { "classic", "forever" }, { deDE = { completion = "Ah ja, ich erinnere mich an Milton. Ein Bücherwurm, ganz ohne Zweifel. Der Gute.\n\nUnd er hat Recht. In den Ruinen von Alterac liegt immer noch ein großer Wissenschatz, der möglicherweise für immer verloren geht!\n\nIn Alterac leben jetzt Oger, und die zeigen kein großes Interesse an höherer Bildung." }, enUS = { completion = "Ah yes, I remember Milton.  A bookworm, no doubt.  Bless him.\n\nAnd he's right.  The Ruins of Alterac still hold stores of knowledge in danger of being lost!\n\nOgres now dwell in Alterac, and they don't care much for higher learning." } })
apply(539, { "classic", "forever" }, { deDE = { progress = "Ihr hattet den direkten Befehl, den Azurschacht anzugreifen. Ihr solltet besser gute Gründe für Euer Verbleiben in Tarrens Mühle haben, oder ich werde Euch wegen Verrates köpfen lassen.", completion = "Die dunkle Fürstin wird erfreut sein, eine neue Mine ihr Eigen zu nennen, mit der sie ihre Soldaten bewaffnen kann." }, enUS = { progress = "You were given direct orders to attack the Azureload Mine.  Your reasons for loafing about Tarren Mill better be good or I will behead you for treason.", completion = "The Dark Lady will be pleased when she learns that she has a new mine from which she can arm her soldiers." } })
apply(540, { "classic", "forever" }, { deDE = { progress = "Ich wünschte, ich könnte ebenfalls die Ruinen absuchen, aber ich befürchte meine Knochen werden mich beim Bergsteigen nicht halten können. Wie dem auch sei, wie geht Eure Wissensjagd voran, {name}?", completion = "Oh, Ihr habt sie schon! Wie wunderbar! Ich muss sofort mit dem Studium des Arms von Gri'lek beginnen!" }, enUS = { progress = "I wish I could search the ruins too, but I fear these bones wouldn't hold me during my climb up the mountains.  However, how does your hunt for knowledge progress, {name}?", completion = "Oh, you got them!  Splendid!  I must begin studying the Arm of Gri'lek immediately!" } })
apply(541, { "classic", "forever" }, { deDE = { completion = "Eure Taten auf dem Schlachtfeld sind des höchsten Lobes wert." }, enUS = { completion = "Your actions on the battlefield are worthy of the highest praise." } })
apply(542, { "classic", "forever" }, { deDE = { progress = "{name}, Ihr seid zurück! Wie lief Euer Ausflug nach Alterac? Habt Ihr etwas mit zurückgebracht?", completion = "Meine Güte! Seht Euch das an! Ich kann kaum glauben, dass sie die Zerstörung von Alterac überstehen konnten. Und dann noch all diese Oger!\n\nDanke, {name}. Ich danke Euch wirklich sehr! Ihr wart dabei behilflich, menschliches Wissen zu bewahren, und Ihr tragt zur Größe der Königlichen Bibliothek von Stormwind bei." }, enUS = { progress = "{name}, you've returned!  How did your foray into Alterac go?  Did you bring anything back with you?", completion = "My oh my!  Look at these!  I can't believe they survived the ruination of Alterac.  And all those ogres too!\n\nThank you, {name}.  Thank you so much!  You have helped preserve human knowledge, and you add to the grandeur of the Royal Library of Stormwind." } })
apply(543, { "classic", "forever" }, { deDE = { progress = "Willkommen, {name}. Bitte versucht, nicht auf meine Hosenmanschetten zu treten. Dieses Gewand ist gerade neu geschneidert worden.", completion = "Ah, dies ist superb. Natürlich muss sie erst gereinigt werden, aber Ihr habt Euch wirklich übertroffen, {name}. Ich werde veranlassen, dass jemand die Tiara vorbereitet und sie schnellstens in unserer Sammlung aufstellt.\n\nIhr werdet mir sicherlich zustimmen, dass unsere Dankbarkeit genauso groß ist, wie unsere Sammlung." }, enUS = { progress = "Salutations, {name}.  Do try to avoid stepping on my pant cuffs.  This outfit is newly tailored.", completion = "Ah, this is splendid.  This will have to be cleaned of course, but you really outdid yourself, {name}.  I will have someone prepare the tiara and place it within our collection posthaste.\n\nAs I'm sure you will agree, our gratitude is as grand as our collection." } })
apply(544, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Diebe gefunden? Und was wichtiger ist, habt Ihr das gefunden, was sie gestohlen haben?", completion = "Ihr habt den Verlassenen einen großen Dienst erwiesen, {name}. Diese Artefakte wurden schmerzlichst vermisst.\n\nUnd es ist gut zu hören, dass Kegan und die anderen Verräter ihre gerechte Strafe gefunden haben." }, enUS = { progress = "Did you find the thieves?  And more importantly, did you find what they stole?", completion = "You have done a great service for the Forsaken, {name}.  These artifacts have been sorely missed.\n\nAnd it is good to hear that Kegan and the other betrayers have found justice." } })
apply(545, { "classic", "forever" }, { deDE = { completion = "Sehr gut. Diese Ruinen sollten jetzt sicher genug für eine Suche sein, vorausgesetzt, man ist vorsichtig.\n\nIch danke Euch, {name}." }, enUS = { completion = "Very good.  Those ruins should now be safe enough to search, if one is careful.\n\nThank you, {name}." } })
apply(546, { "classic", "forever" }, { deDE = { progress = "{name}, das Glückskind kehrt also zurück? Wie viele Menschen habt Ihr heute getötet? Hunderte, hoffe ich doch!\n\nHabt Ihr ein paar Schädel für mich?", completion = "Wundervolle Schädel! So wunderschön! Ich bin Euch was schuldig, versprochen, {name}!" }, enUS = { progress = "So the lucky {name} returns?  How many humans have you slaughtered today?  Hundreds I do hope!\n\nHave you any skulls for me?", completion = "Precious skulls!  So beautiful!  I owe you as promised, {name}!" } })
apply(547, { "classic", "forever" }, { deDE = { progress = "Konntet Ihr mein Schwert zurückholen, {name}? Hochexekutorin Darthalia wird mich an den Dachbalken aufhängen, wenn sie etwas von meiner Dummheit erfährt.", completion = "Ihr habt es gefunden!\n\nAh, ich fühl mich so vollständig, jetzt wo mein wunderbares Schwert wieder in meiner Hand ist. Ich danke Euch vielmals!" }, enUS = { progress = "Were you able to retrieve my sword, {name}?  High Executor Darthalia will hang me from the rafters if she discovers my folly.", completion = "You found it!\n\nAh, I feel so complete with my precious sword back in my hand.  Many thanks to you!" } })
apply(549, { "classic", "forever" }, { deDE = { completion = "Exzellent, {class}. Wenn Ihr so weitermacht, wird die Syndikatsplage schon bald der Vergangenheit dieses Landes angehören." }, enUS = { completion = "Excellent, {class}. At this rate, the Syndicate pest will be rid from the land in no time." } })
apply(550, { "classic", "forever" }, { deDE = { progress = "Was führt Euch den ganzen Weg vom Schlachtfeld nach Undercity, {class}?", completion = "Ihr seid also der berüchtigte {class}, der einen solch entscheidenden Schlag gegen die Allianzkräfte im Vorgebirge von Hillsbrad geführt hat... Die Nachricht Eurer glorreichen Taten kam schnell bis nach Undercity.\n\nIhr habt eine schöne Zukunft in den Rängen der dunklen Fürstin vor Euch, wenn Ihr weiterhin solche Führungskraft und solch ein Geschick in der Schlacht zeigt.\n\nWährend unsere größte Bedrohung die Geißelarmee des Lichkönigs ist, die von Norden her einmarschiert, behindert das \"Menschenproblem\" weiterhin unsere Schlachtpläne. Ihr jedoch habt uns gezeigt, dass Menschen tatsächlich besiegt werden können." }, enUS = { progress = "What brings a {class} all the way to the Undercity from the battlefield?", completion = "So you are the infamous {class} who struck such a decisive blow against the Alliance forces in the Hillsbrad Foothills?  Word of your glorious exploits traveled quickly to the Undercity.\n\nYou have quite a future in the Dark Lady's ranks if you continue to show such leadership and expertise in battle.\n\nWhile our primary threat is the Lich King's Scourge army descending from the north, the human \"problem\" continues to impede our battle plans.  You, however, have shown that the humans can and will fall." } })
apply(551, { "classic", "forever" }, { deDE = { progress = "Oh. Ihr habt etwas für mich, auf das ich einen Blick werfen soll? Ein Teil der Lehren, die Ihr oben in den Bergen gesammelt habt, wie ich hoffe...", completion = "Weitere verschlüsselte Notizen?\n\nIch wünschte ich hätte das Talent, um all diese seltsamen Schriften entziffern zu können, die jetzt von Alterac hereinkommen. Aber leider verfüge ich nicht über das passende Wissen." }, enUS = { progress = "Oh.  You have something you'd like me to look at?  Some scrap of lore gathered from up in the mountains, I hope...", completion = "More encrypted notes?\n\nI wish I had the talents to decrypt all the strange bits of writing that trickle down from Alterac.  But I'm afraid I lack the knowledge." } })
apply(552, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Helculars Rute bereits gefunden? Es gibt in dieser Gegend so viele Yetis, dass es bestimmt schwierig sein wird, sie aufzufinden. Aber wir müssen sie erst haben, bevor wir weitermachen können.", completion = "Ihr habt sie gefunden! Vorzüglich, {name}!" }, enUS = { progress = "Have you recovered Helcular's Rod yet?  There are so many Yeti in this region, it will be very difficult to locate.  But we must have it in order to proceed.", completion = "You found it!  Most excellent, {name}!" } })
apply(553, { "classic", "forever" }, { deDE = { progress = "Helculars Grab brodelt vor mystischer Energie.", completion = "Ein großes Grollen steigt vom Boden herauf." }, enUS = { progress = "Helcular's grave teems with a mystical energy.", completion = "A great rumbling emanates from the ground." } })
apply(554, { "classic", "forever" }, { deDE = { progress = "Noch mehr Unterbrechungen?\n\nAh, dieses Pergament ist mit einem sehr verzwickten, fein gewobenen Zauber umhüllt. Natürlich kann ich ihn entwirren, aber das wird seine Zeit dauern. Und meine Zeit ist mir sehr kostbar...\n\nVielleicht kaufe ich es Euch einfach ab?", completion = "Eine weise Entscheidung. Ich glaube nicht, dass es noch einen weiteren Gelehrten außer mir selbst gibt, der die Fähigkeit hat, diese Schriftrolle zu übersetzen. Und falls sein Inhalt sich als interessant erweisen sollte, keine Angst. Ich werde nach Euch schicken." }, enUS = { progress = "More interruptions?\n\nAh, this parchment is covered with a very intricate, finely woven spell.  I can untangle it, of course, but it's going to take time.  And time is very valuable to me...\n\nPerhaps I will just purchase it from you?", completion = "A wise decision.  I don't believe there is a scholar other than myself with the skills to translate this scroll.  And if its contents prove interesting, fear not.  I will send for you." } })
apply(555, { "classic", "forever" }, { deDE = { progress = "Hattet Ihr Erfolg bei der Suche nach den Zutaten? Ich sag Euch, dieses Gebiet ist nicht mehr der friedliche Ort, der er einst war. Wenn nur diese Aufstände niemals stattgefunden hätten...", completion = "Das wird allen sehr gefallen: Die milde Schildkrötensuppe von Küchenchef Jessen ist wieder auf dem Menüplan!" }, enUS = { progress = "Any luck finding the ingredients?  I'll tell you, this territory isn't the peaceful place it once was.  Ah, if only this unrest never occurred. . .", completion = "Everyone will be so pleased: Chef Jessen's Soothing Turtle Bisque is served once again!" } })
apply(556, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die abgenutzten Steinmarken, {name}? Der Magus kann es kaum erwarten, ihren Geheimnissen auf den Grund zu gehen.", completion = "Diese eignen sich wunderbar. Obwohl es scheint, als sei ihre Magie verblasst, ist es wohl am besten, wenn der Magus seine ersten Experimente an solch trägen Exemplaren wie diesen hier durchführt.\n\nIch danke Euch, {name}." }, enUS = { progress = "Do you have the Worn Stone Tokens, {name}?  The Magus is eager to unlock their secrets.", completion = "These will do nicely.  Although it looks like their magic is faded, it would be best if the Magus' initial experiments were on inert specimens such as these.\n\nThank you, {name}." } })
apply(557, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Elementare sind eine schwere Beute, aber Ihr seid dieser Aufgabe gewachsen. Habt Ihr die Armschienen der Bindung?", completion = "Ihr habt sie gefunden. Ich hoffe, dass die Elementare, von denen Ihr diese Schienen habt, auch einverstanden waren...\n\nHmm... es scheint, dass mit dem Tod nicht nur mein Herz aufhörte zu schlagen, auch mein komisches Talent ist dabei draufgegangen.\n\nIch danke Euch, {name}. Ihr habt dem Magus einen guten Dienst erwiesen und damit auch der dunklen Fürstin." }, enUS = { progress = "Hello, {name}.  Elementals are tough quarry, but I know you're up to the task.  Do you have those bracers of binding?", completion = "You found them.  I trust the elementals from which you removed these bracers were amenable?\n\nHm...death has not only stopped my heart, but robbed me of my comedic timing, it seems.\n\nWell thank you, {name}.  You serve the Magus, and hence the Dark Lady, well." } })
apply(559, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Köpfe für mich besorgt, {name}?", completion = "Oh liebes Licht... die tropfen ja auf den Boden.\n\nIch kann diese Dinger ja nicht anfassen. Fische, gut und schön, aber wenn sie Beine kriegen und herumlaufen... Hab seit Wochen keinen Fisch gegessen, und ich sag Euch, in Southshore heißt das, dass man nicht viel isst." }, enUS = { progress = "Did you get those heads for me, {name}?", completion = "Oh for the Love of the Light... they're dripping on the ground.\n\nCan't stand touching those things, myself. Fish are all well and good, but when they grow legs and start walking around... Haven't eaten a fish in weeks, let me tell you, and in Southshore, that means you aren't eating much." } })
apply(560, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, Bürger. Seid Ihr gekommen, um bei der Aufrechterhaltung der Sicherheit von Southshore behilflich zu sein?", completion = "Ihr seid Farrens Junge für alles, wie?\n\nWenn Ihr Farren beim Sammeln dieser Köpfe behilflich wart, dann vielen Dank. Southshore braucht eifrige Arbeiter und große Bemühungen um seinen Schutz aufrechtzuerhalten." }, enUS = { progress = "Greetings, citizen. Have you come to lend your arm to upholding the safety of Southshore?", completion = "Farren's errand boy, are you?\n\nIf you assisted Farren in procuring these heads, then thank you. Southshore needs hard workers and effort to maintain its protection." } })
apply(561, { "classic", "forever" }, { deDE = { completion = "Die Naga, wie? Redpath muss gerade dieselben Informationen erhalten haben wie ich... Ha! Er will 'ne Beförderung und ich darf mich dafür abrackern, kommt gar nicht in Frage. Lasst es mich erklären." }, enUS = { completion = "The naga, eh? Redpath must have just received the same information as me... Ha! He'll not receive a promotion from my toil. Let me explain." } })
